import { SeededRNG } from '../core/rng.js';
import type { LSABootstrapEdge, LSABootstrapOptions, LSABootstrapResult, LSACertaintyOptions, LSACertaintyResult, LSAFit, LSAGroup, LSAPermutationOptions, LSAPermutationResult, LSAReliabilityOptions, LSAReliabilityResult, LSAStabilityOptions, LSAStabilityResult, Matrix } from './types.js';
import { lsa } from './fit.js';
import { betaCDF, betaQuantile, flattenColumnMajor, mean, pearson, quantile7, sampleSD, spearman } from './math.js';

const rngFor = (seed?:number) => new SeededRNG(seed ?? (Date.now() & 0xffffffff));
function refit(fit:LSAFit, sequences:number[][]):LSAFit{return lsa(sequences.map(s=>s.map(v=>v+1)),{...fit.params,labels:fit.data.labels,group:null}) as LSAFit;}
function columns(x:Matrix):number[][]{if(!x.length)return[];return Array.from({length:x[0]!.length},(_,j)=>x.map(r=>r[j]!));}
function validateIterations(n:number):number{if(!Number.isInteger(n)||n<1)throw new Error('iterations must be a positive whole number.');return n;}

export function bootstrapLSA(fit:LSAFit,options:LSABootstrapOptions={}):LSABootstrapResult{
  if(fit.data.source!=='events')throw new Error('bootstrapLSA requires event-level input.');const iterations=validateIterations(options.iterations??1000),confidenceLevel=options.confidenceLevel??.95,rng=rngFor(options.seed),seqs=fit.data.sequences!,level=options.level==='event'||(options.level!=='sequence'&&seqs.length<2)?'event':'sequence';
  let indices:number[][];if(options.indices){indices=options.indices.slice(0,iterations).map(r=>r.slice());if(indices.length<iterations)throw new Error('indices must contain one row per iteration.');const width=level==='sequence'?seqs.length:fit.data.nEvents,hi=width;if(indices.some(r=>r.length!==width||r.some(v=>!Number.isInteger(v)||v<0||v>=hi)))throw new Error(`indices rows must contain exactly ${width} zero-based valid indices.`);}else if(level==='sequence')indices=Array.from({length:iterations},()=>rng.choice(seqs.length,seqs.length));else{const T=fit.data.nEvents,block=Math.floor(options.blockLength??Math.ceil(Math.sqrt(T))),p=1/block;indices=Array.from({length:iterations},()=>{const out:number[]=[];while(out.length<T){const start=rng.randInt(T),u=Math.max(Number.MIN_VALUE,rng.random()),len=1+Math.floor(Math.log(u)/Math.log(1-p));for(let q=0;q<len&&out.length<T;q++)out.push((start+q)%T);}return out;});}
  const observedRows:Matrix=[],residualRows:Matrix=[],probRows:Matrix=[],qRows:Matrix=[];for(const idx of indices){const sampled=level==='sequence'?idx.map(i=>seqs[i]!.slice()):[idx.map(i=>fit.data.events![i]!)];const f=refit(fit,sampled);observedRows.push(flattenColumnMajor(f.observed));residualRows.push(flattenColumnMajor(f.adjustedResiduals));probRows.push(flattenColumnMajor(f.probability));qRows.push(flattenColumnMajor(f.yulesQ));}
  const edges=summarizeBootstrap(fit,observedRows,residualRows,probRows,qRows,confidenceLevel);return{kind:'lsa_bootstrap',edges,bootObserved:observedRows,bootAdjustedResiduals:residualRows,bootProbability:probRows,bootYulesQ:qRows,iterations,level,confidenceLevel,indicesUsed:indices,fit};
}
function summarizeBootstrap(fit:LSAFit,obs:Matrix,res:Matrix,prob:Matrix,q:Matrix,level:number):LSABootstrapEdge[]{const lo=(1-level)/2,source=[columns(obs),columns(res),columns(prob),columns(q)],original=[flattenColumnMajor(fit.observed),flattenColumnMajor(fit.adjustedResiduals),flattenColumnMajor(fit.probability),flattenColumnMajor(fit.yulesQ)];return fit.edges.map((e,i)=>{const oc=source[0]![i]!,ar=source[1]![i]!,pr=source[2]![i]!,yq=source[3]![i]!,o0=original[0]![i]!,a0=original[1]![i]!,p0=original[2]![i]!,q0=original[3]![i]!;const low=(x:number[])=>quantile7(x,lo),high=(x:number[])=>quantile7(x,1-lo),finite=ar.filter(Number.isFinite),pboot=finite.length?2*Math.min(finite.filter(v=>v<=0).length/finite.length,finite.filter(v=>v>=0).length/finite.length):NaN,al=low(ar),ah=high(ar);return{from:e.from,to:e.to,observed:o0,countMean:mean(oc),countSE:sampleSD(oc),countCILow:low(oc),countCIHigh:high(oc),adjResObserved:a0,adjResMean:mean(ar),adjResSE:sampleSD(ar),adjResCILow:al,adjResCIHigh:ah,adjResPBootstrap:pboot,adjResStable:Number.isFinite(al)&&Number.isFinite(ah)&&Math.sign(al)===Math.sign(ah)&&al!==0&&ah!==0,probObserved:p0,probMean:mean(pr),probCILow:low(pr),probCIHigh:high(pr),yulesQObserved:q0,yulesQMean:mean(yq),yulesQCILow:low(yq),yulesQCIHigh:high(yq)};});}

export function certaintyLSA(fit:LSAFit|LSAGroup,options:LSACertaintyOptions={}):LSACertaintyResult|Record<string,LSACertaintyResult>{if(fit.kind==='lsa_group')return Object.fromEntries(fit.levels.map(g=>[g,certaintyLSA(fit.groups[g]!,options) as LSACertaintyResult]));const prior=options.prior??.5,confidenceLevel=options.confidenceLevel??.95,inference=options.inference??'stability',range=options.consistencyRange??[.75,1.25],tail=(1-confidenceLevel)/2,threshold=options.edgeThreshold??quantile7(flattenColumnMajor(fit.probability).filter(v=>Number.isFinite(v)&&v>0),.1);const edges=fit.edges.map(e=>{const i=e.fromId-1,j=e.toId-1,a=fit.observed[i]![j]!+prior,rowA=fit.observed[i]!.reduce((s,v)=>s+v+prior,0),b=rowA-a,pm=a/rowA,se=Math.sqrt(a*b/(rowA**2*(rowA+1))),low=betaQuantile(tail,a,b),high=betaQuantile(1-tail,a,b),p=inference==='stability'?betaCDF(Math.min(e.prob*range[0],e.prob*range[1]),a,b)+1-betaCDF(Math.max(e.prob*range[0],e.prob*range[1]),a,b):betaCDF(threshold,a,b),valid=Number.isFinite(e.prob)&&fit.params.structuralZeros?.[i]?.[j]!==0,stable=valid&&e.prob>0&&p<1-confidenceLevel;return{from:e.from,to:e.to,observed:e.count,probObserved:e.prob,probMean:valid?pm:NaN,probSE:valid?se:NaN,probCILow:valid?low:NaN,probCIHigh:valid?high:NaN,pValue:valid?p:NaN,stable,adjResObserved:e.adjRes,adjResStable:stable};});return{kind:'lsa_certainty',edges,prior,confidenceLevel,inference,fit};}

export function permuteLSA(fit:LSAFit,options:LSAPermutationOptions={}):LSAPermutationResult{if(fit.data.source!=='events')throw new Error('permuteLSA requires event-level input.');const iterations=validateIterations(options.iterations??1000),within=options.withinSequence??true,rng=rngFor(options.seed),seqs=fit.data.sequences!,T=fit.data.nEvents;let shuffles=options.shuffles;if(shuffles){if(shuffles.length<iterations||shuffles.slice(0,iterations).some(p=>p.length!==T||new Set(p).size!==T||p.some(v=>!Number.isInteger(v)||v<0||v>=T)))throw new Error(`Every shuffle must be a zero-based permutation of 0..${T-1}.`);}const rows:Matrix=[];for(let b=0;b<iterations;b++){let sampled:number[][];if(shuffles){const events=shuffles[b]!.map(i=>fit.data.events![i]!);sampled=[];let q=0;for(const s of seqs)sampled.push(events.slice(q,q+=s.length));}else sampled=within?seqs.map(s=>rng.shuffle(s.slice())):[rng.shuffle(fit.data.events!.slice())];rows.push(flattenColumnMajor(refit(fit,sampled).adjustedResiduals));}const observed=flattenColumnMajor(fit.adjustedResiduals),edges=fit.edges.map((e,i)=>{const nulls=rows.map(r=>r[i]!).filter(Number.isFinite),p=Number.isFinite(observed[i]!)&&nulls.length?(1+nulls.filter(v=>Math.abs(v)>=Math.abs(observed[i]!)).length)/(1+nulls.length):NaN;return{from:e.from,to:e.to,observedCount:e.count,observedAdjRes:e.adjRes,pPermutation:p,significant:Number.isFinite(p)&&p<fit.params.alpha};});return{kind:'lsa_permutation',edges,permutationAdjustedResiduals:rows,iterations,withinSequence:within,fit};}

export function stabilityLSA(fit:LSAFit,options:LSAStabilityOptions={}):LSAStabilityResult{if(fit.data.source!=='events')throw new Error('stabilityLSA requires event-level input.');const iterations=validateIterations(options.iterations??options.subsamples?.length??500),proportion=options.proportion??.8,minStable=options.minStable??.95,rng=rngFor(options.seed),seqs=fit.data.sequences!,rows:boolean[][]=[];if(options.subsamples&&(options.subsamples.length<iterations||options.subsamples.some(s=>!s.length||s.some(i=>!Number.isInteger(i)||i<0||i>=seqs.length))))throw new Error('subsamples must contain valid zero-based sequence indices.');for(let b=0;b<iterations;b++){let sampled:number[][];if(options.subsamples)sampled=options.subsamples[b]!.map(i=>seqs[i]!);else if(seqs.length>=2)sampled=rng.choiceWithoutReplacement(seqs.length,Math.max(1,Math.round(seqs.length*proportion))).map(i=>seqs[i]!);else{const m=Math.max(2,Math.round(seqs[0]!.length*proportion)),start=rng.randInt(seqs[0]!.length-m+1);sampled=[seqs[0]!.slice(start,start+m)];}try{rows.push(flattenColumnMajor(refit(fit,sampled).pValues).map(p=>Number.isFinite(p)&&p<fit.params.alpha));}catch{rows.push(Array(fit.edges.length).fill(false));}}const edges=fit.edges.map((e,i)=>{const stability=rows.filter(r=>r[i]).length/iterations;return{from:e.from,to:e.to,observedSignificant:e.significant,stability,stable:stability>=minStable};});return{kind:'lsa_stability',edges,stabilityMatrix:rows,iterations,proportion,minStable,fit};}

export function reliabilityLSA(fit:LSAFit|LSAGroup,options:LSAReliabilityOptions={}):LSAReliabilityResult|Record<string,LSAReliabilityResult>{if(fit.kind==='lsa_group')return Object.fromEntries(fit.levels.map(g=>[g,reliabilityLSA(fit.groups[g]!,options) as LSAReliabilityResult]));if(fit.data.source!=='events'||fit.data.nSequences<2)throw new Error('reliabilityLSA requires at least two event sequences.');const iterations=validateIterations(options.iterations??options.splits?.length??100),weights=options.weights??'prob',method=options.method??'pearson',rng=rngFor(options.seed),seqs=fit.data.sequences!,cors:number[]=[];if(options.splits&&(options.splits.length<iterations||options.splits.some(s=>!s.length||s.length>=seqs.length||new Set(s).size!==s.length||s.some(i=>!Number.isInteger(i)||i<0||i>=seqs.length))))throw new Error('splits must contain unique valid zero-based indices for a non-empty first half.');const pull=(f:LSAFit)=>flattenColumnMajor(weights==='prob'?f.probability:weights==='count'?f.observed:f.adjustedResiduals);for(let b=0;b<iterations;b++){const a=options.splits?.[b]?.slice()??rng.choiceWithoutReplacement(seqs.length,Math.max(1,Math.floor(seqs.length/2))),set=new Set(a),bb=seqs.map((_,i)=>i).filter(i=>!set.has(i));try{const x=pull(refit(fit,a.map(i=>seqs[i]!))),y=pull(refit(fit,bb.map(i=>seqs[i]!)));cors.push(method==='pearson'?pearson(x,y):spearman(x,y));}catch{cors.push(NaN);}}const finite=cors.filter(Number.isFinite);return{kind:'lsa_reliability',correlations:cors,mean:mean(finite),sd:sampleSD(finite),ciLow:quantile7(finite,.025),ciHigh:quantile7(finite,.975),iterations,weights,method,nSequences:seqs.length,fit};}
