import type { LSAData, LSAInput, LSATransitions, Matrix } from './types.js';
import { cloneMatrix, colSums, matrix, rowSums, sum } from './math.js';

const missing = (v: unknown): boolean => v == null || v === '';
const isFiniteNumber = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

export function lsaData(input: LSAInput, labels?: string[] | null): LSAData {
  if (typeof input === 'object' && input !== null && 'source' in input && 'nStates' in input) return input as LSAData;
  if (!Array.isArray(input) || input.length === 0) throw new Error('Input must contain at least one usable sequence.');
  const nested = Array.isArray(input[0]);
  if (nested) {
    const rows = input as unknown[][];
    const squareNumeric = rows.length >= 2 && rows.every((r) => r.length === rows.length && r.every(isFiniteNumber));
    if (squareNumeric) return lsaDataFromMatrix(rows as Matrix, labels);
    return lsaDataFromSequences(rows, labels);
  }
  return lsaDataFromSequences([input as unknown[]], labels);
}

export function lsaDataFromMatrix(observed: Matrix, labels?: string[] | null): LSAData {
  const n = observed.length;
  if (n < 2 || observed.some((r) => r.length !== n)) throw new Error('Transition matrix must be square and at least 2 x 2.');
  if (observed.flat().some((v) => !Number.isFinite(v) || v < 0)) throw new Error('Transition matrix must contain finite non-negative counts.');
  const resolved = labels?.slice() ?? Array.from({ length: n }, (_, i) => `Code ${i + 1}`);
  if (resolved.length !== n || new Set(resolved).size !== n) throw new Error('labels must contain one unique name per state.');
  return { events: null, seqId: null, labels: resolved, nStates: n, nSequences: NaN, nEvents: NaN,
    transitionsPerSequence: [], source: 'transitions', observedInput: cloneMatrix(observed), sequences: null };
}

export function lsaDataFromSequences(raw: unknown[][], labels?: string[] | null): LSAData {
  const seqs = raw.map((s) => s.filter((v) => !missing(v))).filter((s) => s.length > 0);
  if (!seqs.length) throw new Error('No usable sequences in input after missing values were removed.');
  const flat = seqs.flat();
  let resolvedLabels: string[]; let mapValue: (v: unknown) => number;
  if (labels) {
    resolvedLabels = labels.map(String);
    if (new Set(resolvedLabels).size !== resolvedLabels.length) throw new Error('labels must be unique.');
    mapValue = (v) => {
      if (typeof v === 'number') {
        if (!Number.isFinite(v) || !Number.isInteger(v) || v < 1 || v > resolvedLabels.length) throw new Error('Numeric event codes must be finite whole numbers within labels.');
        return v - 1;
      }
      const i = resolvedLabels.indexOf(String(v)); if (i < 0) throw new Error(`Event '${String(v)}' is not in labels.`); return i;
    };
  } else if (flat.every((v) => typeof v === 'number' || typeof v === 'boolean')) {
    const ints = flat.map(Number);
    if (ints.some((v) => !Number.isFinite(v) || !Number.isInteger(v) || v < 1)) throw new Error('Numeric event codes must be finite whole numbers >= 1.');
    const k = Math.max(...ints); resolvedLabels = Array.from({ length: k }, (_, i) => `Code ${i + 1}`); mapValue = (v) => Number(v) - 1;
  } else {
    resolvedLabels = [...new Set(flat.map(String))].sort(); mapValue = (v) => resolvedLabels.indexOf(String(v));
  }
  const sequences = seqs.map((s) => s.map(mapValue));
  const events = sequences.flat(); const seqId = sequences.flatMap((s, i) => Array(s.length).fill(i));
  return { events, seqId, labels: resolvedLabels, nStates: resolvedLabels.length, nSequences: sequences.length,
    nEvents: events.length, transitionsPerSequence: sequences.map((s) => Math.max(0, s.length - 1)), source: 'events', observedInput: null, sequences };
}

export function lsaTransitions(input: LSAInput | LSAData, lag = 1): LSATransitions {
  if (!Number.isFinite(lag) || !Number.isInteger(lag)) throw new Error('lag must be a finite whole number.');
  const d = lsaData(input as LSAInput); let observed: Matrix;
  if (d.source === 'transitions') {
    if (lag !== 1) throw new Error('Pre-computed transition matrices only support lag = 1.'); observed = cloneMatrix(d.observedInput!);
  } else {
    observed = matrix(d.nStates, d.nStates);
    for (const sequence of d.sequences!) {
      if (lag >= 0) for (let i = 0; i + lag < sequence.length; i++) observed[sequence[i]!]![sequence[i + lag]!]!++;
      else for (let i = -lag; i < sequence.length; i++) observed[sequence[i]!]![sequence[i + lag]!]!++;
    }
  }
  const rt = rowSums(observed), ct = colSums(observed), total = sum(rt);
  const edges = [];
  for (let j = 0; j < d.nStates; j++) for (let i = 0; i < d.nStates; i++) edges.push({ from: d.labels[i]!, to: d.labels[j]!, lag,
    count: observed[i]![j]!, rowTotal: rt[i]!, colTotal: ct[j]!, nTransitions: total });
  return { observed, rowTotals: rt, colTotals: ct, nTransitions: total, lag, labels: d.labels.slice(), edges };
}

export interface LongEventRow { [key: string]: unknown; }
export interface PrepareLongOptions { actor?: string; action: string; time?: string; order?: string; session?: string; group?: string; timeThreshold?: number; unixTimeUnit?: 'seconds' | 'milliseconds' | 'microseconds'; }
export function prepareLong(rows: LongEventRow[], options: PrepareLongOptions): { sequences: string[][]; groups?: string[] } {
  if (!Array.isArray(rows)) throw new Error('Long-format input must be an array of row objects.');
  const { actor, action, time, order, session, group } = options; const threshold = options.timeThreshold ?? 900;
  for (const col of [actor, action, time, order, session, group].filter(Boolean) as string[]) if (rows.some((r) => !(col in r))) throw new Error(`Column '${col}' was not found.`);
  const div = options.unixTimeUnit === 'milliseconds' ? 1e3 : options.unixTimeUnit === 'microseconds' ? 1e6 : 1;
  const timeValue = (v: unknown): number => { if (typeof v === 'number') return v / div; const t = Date.parse(String(v)) / 1000; if (!Number.isFinite(t)) throw new Error(`Could not parse time '${String(v)}'.`); return t; };
  const buckets = new Map<string, number[]>(); rows.forEach((r, i) => { const key = `${actor ? String(r[actor]) : ''}\0${session ? String(r[session]) : ''}`; const b = buckets.get(key) ?? []; b.push(i); buckets.set(key, b); });
  const sequences: string[][] = [], groups: string[] = [];
  for (const indices of buckets.values()) {
    indices.sort((a, b) => order ? Number(rows[a]![order]) - Number(rows[b]![order]) : time ? timeValue(rows[a]![time]) - timeValue(rows[b]![time]) : a - b);
    if (group) { const gs = [...new Set(indices.map((i) => String(rows[i]![group])))]; if (gs.length !== 1) throw new Error(`Group column '${group}' must be constant within every recovered sequence.`); }
    let current: string[] = [], previous = NaN;
    for (const i of indices) { const t = time ? timeValue(rows[i]![time]) : NaN; if (!session && time && current.length && t - previous > threshold) { sequences.push(current); if (group) groups.push(String(rows[indices[0]!]![group])); current = []; } current.push(String(rows[i]![action])); previous = t; }
    if (current.length) { sequences.push(current); if (group) groups.push(String(rows[indices[0]!]![group])); }
  }
  return group ? { sequences, groups } : { sequences };
}
