import type { LSAAlternative, LSAData, LSAEdge, LSAFit, LSAGroup, LSAInput, LSALags, LSAOptions, LSAProfileRow, LSATest, LSATNA, Matrix, TransitionFilterOptions } from './types.js';
import { lsaData, lsaDataFromSequences, lsaTransitions, prepareLong } from './data.js';
import { getLSAEngine } from './engines.js';
import { chiSquareUpper, cloneMatrix, colSums, flattenColumnMajor, matrix, rowSums } from './math.js';

const defaults = { lag: 1, engine: 'classical', alternative: 'two.sided' as const, alpha: 0.05, loops: true };
type ResolvedOptions = LSAOptions & { lag: number; engine: string; alternative: LSAAlternative; alpha: number; loops: boolean; params: Record<string, unknown> };
function structuralZeros(value: Matrix | null | undefined, loops: boolean, k: number): Matrix | null {
  if (!value && loops) return null; const out = value ? cloneMatrix(value) : matrix(k, k, 1);
  if (out.length !== k || out.some((r) => r.length !== k || r.some((v) => v !== 0 && v !== 1))) throw new Error(`structuralZeros must be a ${k} x ${k} 0/1 matrix.`);
  if (!loops) for (let i = 0; i < k; i++) out[i]![i] = 0; return out;
}

export function lsa(input: LSAInput, options: LSAOptions = {}): LSAFit | LSAGroup {
  const o: ResolvedOptions = { ...defaults, ...options, engine: String(options.engine ?? defaults.engine), params: options.params ?? {} }; if (!(o.alpha > 0 && o.alpha < 1)) throw new Error('alpha must be between 0 and 1.');
  let preparedInput = input; let longGroups: string[] | undefined;
  if (o.action) { const prepared = prepareLong(input as Array<Record<string, unknown>>, { actor:o.actor, action:o.action, time:o.time, order:o.order, session:o.session, group:typeof o.group==='string'?o.group:undefined, timeThreshold:o.timeThreshold, unixTimeUnit:o.unixTimeUnit }); preparedInput=prepared.sequences; longGroups=prepared.groups; }
  const data = lsaData(preparedInput, o.labels);
  const group = longGroups ?? (Array.isArray(o.group) ? o.group : null);
  if (group) return grouped(data, group, o);
  if (typeof o.group === 'string' && !o.action) throw new Error('A string group name is only valid with long-format action input.');
  return fitOne(data, o);
}
function grouped(data: LSAData, group: Array<string | number>, options: ResolvedOptions): LSAGroup {
  if (data.source !== 'events') throw new Error('Grouped LSA requires event-level sequence data.'); if (group.length !== data.nSequences) throw new Error('group must have one value per sequence.');
  const levels = [...new Set(group.map(String))], groups: Record<string, LSAFit> = {}, groupSizes: number[] = [];
  for (const level of levels) { const seqs = data.sequences!.filter((_, i) => String(group[i]) === level).map((s) => s.map((v) => v + 1)); groupSizes.push(seqs.length); groups[level] = fitOne(lsaDataFromSequences(seqs, data.labels), { ...options, group: null }); }
  return { kind: 'lsa_group', groups, levels, groupSizes, labels: [...data.labels], engine: String(options.engine) };
}
function fitOne(data: LSAData, options: ResolvedOptions): LSAFit {
  const sz = structuralZeros(options.structuralZeros, options.loops, data.nStates), tx = lsaTransitions(data, options.lag), eventTotals = data.events ? Array.from({length:data.nStates},(_,i)=>data.events!.filter(v=>v===i).length) : null;
  const result = getLSAEngine(String(options.engine)).fn({ transitions: tx, structuralZeros: sz, alternative: options.alternative!, nEvents: data.source === 'events' ? data.nEvents : null, eventTotals, params: options.params ?? {} });
  const obs=result.observed,exp=result.expected,prob=result.probability,z=result.adjustedResiduals,p=result.pValues,k=data.nStates,ct=colSums(obs),rt=rowSums(obs);
  const probCol=obs.map((r)=>r.map((v,j)=>ct[j]!>0?v/ct[j]!:NaN)); const edges:LSAEdge[]=[]; const extraVectors:Record<string,number[]>={};
  for(const [name,value] of Object.entries(result.extra))if(Array.isArray(value)&&Array.isArray(value[0]))extraVectors[name]=flattenColumnMajor(value as Matrix);
  let q=0;for(let j=0;j<k;j++)for(let i=0;i<k;i++,q++){const count=obs[i]![j]!,expected=exp[i]![j]!,edge:LSAEdge={from:data.labels[i]!,to:data.labels[j]!,fromId:i+1,toId:j+1,lag:options.lag!,count,expected,prob:prob[i]![j]!,probCol:probCol[i]![j]!,adjRes:z[i]![j]!,p:p[i]![j]!,yulesQ:result.yulesQ[i]![j]!,kappa:result.kappa[i]![j]!,kappaZ:result.kappaZ[i]![j]!,kappaP:result.kappaP[i]![j]!,lift:Number.isFinite(expected)&&expected>0?count/expected:NaN,sign:count>expected?'over':count<expected?'under':'expected',significant:Number.isFinite(p[i]![j]!)&&p[i]![j]!<options.alpha!,weight:count};for(const[name,v]of Object.entries(extraVectors))edge[camel(name)]=v[q]!;edges.push(edge);}
  const lr=result.likelihoodRatio,pearson=lr?pearsonTest(obs,exp,lr.df):null;
  let initialProbabilities:number[]|null=null;if(data.sequences){const first=data.sequences.map(s=>s[0]!);initialProbabilities=Array.from({length:k},(_,i)=>first.filter(v=>v===i).length/first.length);}
  return {kind:'lsa',observed:obs,expected:exp,probability:prob,probabilityColumn:probCol,adjustedResiduals:z,pValues:p,yulesQ:result.yulesQ,kappa:result.kappa,kappaZ:result.kappaZ,kappaP:result.kappaP,likelihoodRatio:lr,pearsonChiSquare:pearson,weights:cloneMatrix(obs),nodes:data.labels.map((label,i)=>({id:i+1,label,name:label,outgoing:rt[i]!,incoming:ct[i]!})),edges,directed:options.engine!=='bidirectional',method:String(options.engine),initialProbabilities,data,params:{lag:options.lag!,engine:String(options.engine),alternative:options.alternative!,alpha:options.alpha!,loops:options.loops!,structuralZeros:sz,params:options.params??{}},meta:{source:data.source,ipf:result.ipf,nEventsUsed:data.source==='events'?data.nEvents:null,extra:result.extra}};
}
function pearsonTest(obs:Matrix,exp:Matrix,df:number):LSATest{let statistic=0;for(let i=0;i<obs.length;i++)for(let j=0;j<obs.length;j++)if(exp[i]![j]!>0)statistic+=(obs[i]![j]!-exp[i]![j]!)**2/exp[i]![j]!;return{statistic,df,p:df>0?chiSquareUpper(statistic,df):NaN};}
const camel=(s:string)=>s.replace(/_([a-z])/g,(_,c:string)=>c.toUpperCase());

export const lsaClassical=(data:LSAInput,options:LSAOptions={})=>lsa(data,{...options,engine:'classical'});
export const lsaTwoCell=(data:LSAInput,options:LSAOptions={})=>lsa(data,{...options,engine:'two_cell'});
export const lsaBidirectional=(data:LSAInput,options:LSAOptions={})=>lsa(data,{...options,engine:'bidirectional'});
export const lsaParallelDominance=(data:LSAInput,options:LSAOptions={})=>lsa(data,{...options,engine:'parallel_dominance'});
export const lsaNonparallelDominance=(data:LSAInput,options:LSAOptions={})=>lsa(data,{...options,engine:'nonparallel_dominance'});

export function transitions(x:LSAFit|LSAGroup|LSALags|{edges:Array<Record<string,unknown>>},options:TransitionFilterOptions={}):Array<Record<string,unknown>>{
  if('kind'in x&&x.kind==='lsa_lags')return x.fits.flatMap(f=>transitions(f,options));
  if('kind'in x&&x.kind==='lsa_group')return x.levels.flatMap(g=>transitions(x.groups[g]!,options).map(r=>({group:g,...r})));
  let e=(x as {edges:Array<Record<string,unknown>>}).edges.map(r=>({...r}));
  if('kind'in x&&x.kind==='lsa'){const f=x as LSAFit,alpha=options.alpha??f.params.alpha,dir=options.direction??'any';e=e.filter(r=>(!options.significant&&dir==='any')||(Number.isFinite(r.p)&&Number(r.p)<alpha));if(dir==='over')e=e.filter(r=>Number(r.adjRes)>0);if(dir==='under')e=e.filter(r=>Number(r.adjRes)<0);if(options.minCount!=null)e=e.filter(r=>Number(r.count)>=options.minCount!);const remove=['fromId','toId','weight'];e=e.map(r=>Object.fromEntries(Object.entries(r).filter(([k])=>!remove.includes(k))));const sort=options.sort??'none';if(sort!=='none')e.sort((a,b)=>{const key=sort==='strength'?'adjRes':sort;return Math.abs(Number(b[key]))-Math.abs(Number(a[key]));});}
  else {if(options.significant)e=e.filter(r=>Boolean(r.significant??r.stable??r.adjResStable));if((options.sort??'none')==='strength')e.sort((a,b)=>{const strength=(r:Record<string,unknown>)=>Math.abs(Number(r.diff??r.observedAdjRes??r.adjResMean??r.probMean??r.stability??0));return strength(b)-strength(a);});} return e;
}
export function nodes(x:LSAFit|LSAGroup):Array<Record<string,unknown>>{if(x.kind==='lsa_group')return x.levels.flatMap(g=>nodes(x.groups[g]!).map(r=>({group:g,...r})));return x.nodes.map(n=>({state:n.label,outgoing:n.outgoing,incoming:n.incoming}));}
export function tests(x:LSAFit|LSAGroup):Array<Record<string,unknown>>{if(x.kind==='lsa_group')return x.levels.flatMap(g=>tests(x.groups[g]!).map(r=>({group:g,...r})));return([['lrx2',x.likelihoodRatio],['x2',x.pearsonChiSquare]]as const).filter(([,v])=>v).map(([test,v])=>({test,...v!}));}
export function transitionProbabilities(x:LSAFit|LSAGroup):Matrix|Record<string,Matrix>{if(x.kind==='lsa_group')return Object.fromEntries(x.levels.map(g=>[g,transitionProbabilities(x.groups[g]!) as Matrix]));return cleanWeight(x,'prob');}
export function initial(x:LSAFit|LSAGroup):Array<Record<string,unknown>>{if(x.kind==='lsa_group')return x.levels.flatMap(g=>initial(x.groups[g]!).map(r=>({group:g,...r})));return x.initialProbabilities?x.data.labels.map((state,i)=>({state,initProb:x.initialProbabilities![i]})):[];}
export function lsaLags(data:LSAInput,lags=[1,2,3],options:LSAOptions={}):LSALags{if(!lags.length||lags.some(l=>!Number.isInteger(l)))throw new Error('lags must contain whole numbers.');return{kind:'lsa_lags',lags:[...lags],fits:lags.map(l=>lsa(data,{...options,lag:l}) as LSAFit)};}
export function lagProfile(input:LSAInput|LSALags,from:string,to:string,lags=[1,2,3],options:LSAOptions={}):LSAProfileRow[]{const x=(input as LSALags).kind==='lsa_lags'?input as LSALags:lsaLags(input as LSAInput,lags,options);return x.fits.map(f=>f.edges.find(e=>e.from===from&&e.to===to)).filter(Boolean).map(e=>({lag:e!.lag,from:e!.from,to:e!.to,count:e!.count,prob:e!.prob,adjRes:e!.adjRes,p:e!.p,significant:e!.significant}));}
export function cleanWeight(fit:LSAFit,weights:'prob'|'count'|'adj_res'|'yules_q'|'lift',positive=false):Matrix{let w:Matrix;if(weights==='prob')w=cloneMatrix(fit.probability);else if(weights==='count')w=cloneMatrix(fit.observed);else if(weights==='adj_res')w=cloneMatrix(fit.adjustedResiduals);else if(weights==='yules_q')w=cloneMatrix(fit.yulesQ);else{w=matrix(fit.data.nStates,fit.data.nStates);for(const e of fit.edges)w[e.fromId-1]![e.toId-1]=e.lift;}for(let i=0;i<w.length;i++)for(let j=0;j<w.length;j++)if(!Number.isFinite(w[i]![j]!)||(positive&&w[i]![j]!<0)||fit.params.structuralZeros?.[i]?.[j]===0)w[i]![j]=0;return w;}
export function lsaToTNA(x:LSAFit|LSAGroup,weights:'prob'|'count'|'adj_res'|'lift'='prob'):LSATNA|Record<string,LSATNA>{if(x.kind==='lsa_group')return Object.fromEntries(x.levels.map(g=>[g,lsaToTNA(x.groups[g]!,weights) as LSATNA]));const resampleable=weights==='prob'||weights==='count';return{weights:cleanWeight(x,weights,weights==='adj_res'),inits:resampleable?(x.initialProbabilities??[]):[],labels:[...x.data.labels],data:resampleable?(x.data.sequences?.map(s=>s.map(v=>v+1))??[]):[],type:weights==='count'?'frequency':'relative'};}
