import { pchisq } from '../stats/group-tests.js';
import type { LSAAlternative, Matrix } from './types.js';

export const matrix = (r: number, c: number, value = 0): Matrix =>
  Array.from({ length: r }, () => Array(c).fill(value));
export const cloneMatrix = (x: Matrix): Matrix => x.map((r) => r.slice());
export const rowSums = (x: Matrix): number[] => x.map((r) => r.reduce((a, b) => a + b, 0));
export const colSums = (x: Matrix): number[] => Array.from({ length: x[0]?.length ?? 0 }, (_, j) => x.reduce((s, r) => s + r[j]!, 0));
export const sum = (x: number[]): number => x.reduce((a, b) => a + b, 0);
export const flattenColumnMajor = (x: Matrix): number[] => {
  const out: number[] = [];
  for (let j = 0; j < (x[0]?.length ?? 0); j++) for (let i = 0; i < x.length; i++) out.push(x[i]![j]!);
  return out;
};
export const fromColumnMajor = (x: number[], n: number): Matrix => {
  const out = matrix(n, n, NaN);
  let k = 0;
  for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) out[i]![j] = x[k++]!;
  return out;
};
export const transpose = (x: Matrix): Matrix => Array.from({ length: x[0]?.length ?? 0 }, (_, j) => x.map((r) => r[j]!));
export const outer = (a: number[], b: number[], fn: (x: number, y: number) => number = (x, y) => x * y): Matrix => a.map((x) => b.map((y) => fn(x, y)));
export const finiteOrNaN = (x: number): number => Number.isFinite(x) ? x : NaN;

export function mean(x: number[]): number {
  const v = x.filter(Number.isFinite); return v.length ? sum(v) / v.length : NaN;
}
export function sampleSD(x: number[]): number {
  const v = x.filter(Number.isFinite); if (v.length < 2) return NaN;
  const m = mean(v); return Math.sqrt(sum(v.map((z) => (z - m) ** 2)) / (v.length - 1));
}
export function quantile7(x: number[], p: number): number {
  const v = x.filter(Number.isFinite).sort((a, b) => a - b);
  if (!v.length) return NaN; if (v.length === 1) return v[0]!;
  const h = (v.length - 1) * p; const lo = Math.floor(h); const f = h - lo;
  return v[lo]! + f * (v[Math.min(lo + 1, v.length - 1)]! - v[lo]!);
}
export function normalP(z: number, alternative: LSAAlternative): number {
  if (!Number.isFinite(z)) return NaN;
  // Z^2 ~ chi-square(1). The shared incomplete-gamma implementation is
  // more accurate in the tails than browser erf approximations.
  const twoSided = pchisq(z * z, 1);
  if (alternative === 'greater') return z >= 0 ? twoSided / 2 : 1 - twoSided / 2;
  if (alternative === 'less') return z <= 0 ? twoSided / 2 : 1 - twoSided / 2;
  return twoSided;
}
export const chiSquareUpper = (q: number, df: number): number => df > 0 ? pchisq(q, df) : NaN;

const polevl = (x:number,c:number[]) => c.slice(1).reduce((a,b)=>a*x+b,c[0]!);
const p1evl = (x:number,c:number[]) => c.slice(1).reduce((a,b)=>a*x+b,x+c[0]!);
/** Cephes ndtr/erfc implementation; full double-precision normal CDF. */
export function normalCDF(x:number):number {
  const z=x/Math.SQRT2;
  if(z<0)return .5*erfc(-z);
  return 1-.5*erfc(z);
}
function erfc(a:number):number{
  const x=Math.abs(a);if(x<1)return 1-erf(a);
  const P=[2.461969814735305e-10,5.641895648310688e-1,7.463210564422699,48.63719709856814,196.5208329560771,526.4451949954774,934.5285271719576,1027.551886895157,557.5353693993274];
  const Q=[13.2281951154745,86.7072140885986,354.9377788878199,975.7085017432055,1823.909166879097,2246.33760818711,1656.663091941613,557.5353408177277];
  const R=[.5641895835477551,1.275366707599781,5.019050422511805,6.160210979930536,7.409742699504489,2.978866653721002];
  const S=[2.260528632201173,9.396035249380015,12.04895398080967,17.08144507475659,9.608968090632859,3.369076451000815];
  const y=Math.exp(-x*x)*(x<8?polevl(x,P)/p1evl(x,Q):polevl(x,R)/p1evl(x,S));return a<0?2-y:y;
}
function erf(x:number):number{const T=[9.604973739870516,90.02601972038427,2232.005345946843,7003.325141128051,55592.30130103949],U=[33.56171416475031,521.3579497801527,4594.323829709801,22629.00006138909,49267.39426086359];if(Math.abs(x)>1)return 1-erfc(x);const z=x*x;return x*polevl(z,T)/p1evl(z,U);}

export function pearson(a: number[], b: number[]): number {
  const pairs = a.map((x, i) => [x, b[i]!] as const).filter(([x, y]) => Number.isFinite(x) && Number.isFinite(y));
  if (pairs.length < 2) return NaN;
  const am = mean(pairs.map((p) => p[0])), bm = mean(pairs.map((p) => p[1]));
  let num = 0, da = 0, db = 0;
  for (const [x, y] of pairs) { num += (x - am) * (y - bm); da += (x - am) ** 2; db += (y - bm) ** 2; }
  return da && db ? num / Math.sqrt(da * db) : NaN;
}
function ranks(x: number[]): number[] {
  const order = x.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  const out = Array(x.length).fill(0); let i = 0;
  while (i < order.length) { let j = i + 1; while (j < order.length && order[j]!.v === order[i]!.v) j++;
    const rank = (i + 1 + j) / 2; for (let k = i; k < j; k++) out[order[k]!.i] = rank; i = j; }
  return out;
}
export const spearman = (a: number[], b: number[]): number => {
  const pairs = a.map((x, i) => [x, b[i]!] as const).filter(([x, y]) => Number.isFinite(x) && Number.isFinite(y));
  return pearson(ranks(pairs.map((p) => p[0])), ranks(pairs.map((p) => p[1])));
};

function logGamma(x: number): number {
  const p = [676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
  if (x < 0.5) return Math.log(Math.PI) - Math.log(Math.sin(Math.PI * x)) - logGamma(1 - x);
  x -= 1; let a = 0.99999999999980993; for (let i = 0; i < p.length; i++) a += p[i]! / (x + i + 1);
  const t = x + p.length - 0.5; return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}
function betaCF(a: number, b: number, x: number): number {
  const eps = 3e-14, tiny = 1e-300, qab = a + b, qap = a + 1, qam = a - 1; let c = 1, d = 1 - qab * x / qap;
  if (Math.abs(d) < tiny) d = tiny; d = 1 / d; let h = d;
  for (let m = 1; m <= 300; m++) { const m2 = 2 * m; let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) < tiny) d = tiny; c = 1 + aa / c; if (Math.abs(c) < tiny) c = tiny; d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2)); d = 1 + aa * d; if (Math.abs(d) < tiny) d = tiny;
    c = 1 + aa / c; if (Math.abs(c) < tiny) c = tiny; d = 1 / d; const del = d * c; h *= del; if (Math.abs(del - 1) < eps) break; }
  return h;
}
export function betaCDF(x: number, a: number, b: number): number {
  if (x <= 0) return 0; if (x >= 1) return 1;
  const bt = Math.exp(logGamma(a + b) - logGamma(a) - logGamma(b) + a * Math.log(x) + b * Math.log1p(-x));
  return x < (a + 1) / (a + b + 2) ? bt * betaCF(a, b, x) / a : 1 - bt * betaCF(b, a, 1 - x) / b;
}
export function betaQuantile(p: number, a: number, b: number): number {
  let lo = 0, hi = 1; for (let i = 0; i < 100; i++) { const mid = (lo + hi) / 2; if (betaCDF(mid, a, b) < p) lo = mid; else hi = mid; } return (lo + hi) / 2;
}
export function binomialP(x: number, n: number, alternative: LSAAlternative): number {
  if (n <= 0) return NaN;
  const logChoose = (nn: number, k: number) => logGamma(nn + 1) - logGamma(k + 1) - logGamma(nn - k + 1);
  const prob = (k: number) => Math.exp(logChoose(n, k) - n * Math.log(2));
  if (alternative === 'greater') return Math.min(1, Array.from({ length: n - x + 1 }, (_, i) => prob(x + i)).reduce((a, b) => a + b, 0));
  if (alternative === 'less') return Math.min(1, Array.from({ length: x + 1 }, (_, i) => prob(i)).reduce((a, b) => a + b, 0));
  const px = prob(x); return Math.min(1, Array.from({ length: n + 1 }, (_, i) => prob(i)).filter((v) => v <= px * (1 + 1e-12)).reduce((a, b) => a + b, 0));
}
