import type { LSAEngine, LSAEngineContext, LSAEngineEntry, LSAEngineResult, LSAIPFOptions, LSAIPFResult, Matrix } from './types.js';
import { binomialP, chiSquareUpper, cloneMatrix, colSums, matrix, normalP, outer, rowSums, sum, transpose } from './math.js';

function validateSquare(x: Matrix): number { const k = x.length; if (k < 2 || x.some((r) => r.length !== k)) throw new Error('Expected a square matrix at least 2 x 2.'); return k; }
export function lsaIPF(observed: Matrix, options: LSAIPFOptions = {}): LSAIPFResult {
  const k = validateSquare(observed); if (observed.flat().some((v) => !Number.isFinite(v) || v < 0)) throw new Error('observed must contain finite non-negative counts.');
  const structure = options.structure ? cloneMatrix(options.structure) : matrix(k, k, 1);
  if (structure.length !== k || structure.some((r) => r.length !== k || r.some((v) => v !== 0 && v !== 1))) throw new Error('structure must be a conformable 0/1 matrix.');
  const rt = rowSums(observed), ct = colSums(observed); if (rt.some((v, i) => v > 0 && sum(structure[i]!) === 0)) throw new Error('IPF is infeasible: positive row with no estimable cells.');
  const sc = colSums(structure); if (ct.some((v, j) => v > 0 && sc[j] === 0)) throw new Error('IPF is infeasible: positive column with no estimable cells.');
  let fit = cloneMatrix(structure), iterations = 0, converged = false, maxMarginDifference = Infinity;
  const tolerance = options.tolerance ?? 1e-8, maxIterations = options.maxIterations ?? 200;
  while (iterations++ < maxIterations) { const rs = rowSums(fit); fit = fit.map((r, i) => r.map((v) => v * (rs[i]! > 0 ? rt[i]! / rs[i]! : 0)));
    const cs = colSums(fit); fit = fit.map((r) => r.map((v, j) => v * (cs[j]! > 0 ? ct[j]! / cs[j]! : 0)));
    maxMarginDifference = Math.max(...rowSums(fit).map((v, i) => Math.abs(v - rt[i]!)), ...colSums(fit).map((v, j) => Math.abs(v - ct[j]!)));
    if (maxMarginDifference < tolerance) { converged = true; break; } }
  return { fit, iterations, converged, maxMarginDifference };
}

const rowNormalize = (x: Matrix): Matrix => { const r = rowSums(x); return x.map((row, i) => row.map((v) => r[i]! > 0 ? v / r[i]! : NaN)); };
function yulesQ(obs: Matrix): Matrix { const rt = rowSums(obs), ct = colSums(obs), n = sum(rt); return obs.map((row, i) => row.map((a, j) => { const b = rt[i]! - a, c = ct[j]! - a, d = n - rt[i]! - ct[j]! + a, den = a * d + b * c; return den > 0 ? (a * d - b * c) / den : NaN; })); }
function naMatrix(k: number): Matrix { return matrix(k, k, NaN); }
function expectedIndependence(obs: Matrix): Matrix { const rt = rowSums(obs), ct = colSums(obs), n = sum(rt); return outer(rt, ct, (a, b) => a * b / n); }
function adjustedResiduals(obs: Matrix, expected: Matrix, structure: Matrix | null): Matrix {
  const k = obs.length, rt = rowSums(obs), ct = colSums(obs), n = sum(rt);
  if (!structure) return obs.map((row, i) => row.map((o, j) => { const d = expected[i]![j]! * (1 - rt[i]! / n) * (1 - ct[j]! / n); return Number.isFinite(d) && d > 0 ? (o - expected[i]![j]!) / Math.sqrt(d) : NaN; }));
  const cells: Array<[number, number]> = []; for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) if (structure[i]![j] === 1) cells.push([i, j]);
  if (!cells.length) return naMatrix(k);
  const p = 1 + (k - 1) * 2; const X = cells.map(([i, j]) => [1, ...Array.from({ length: k - 1 }, (_, q) => i === q + 1 ? 1 : 0), ...Array.from({ length: k - 1 }, (_, q) => j === q + 1 ? 1 : 0)]);
  const A = matrix(p, p); for (let a = 0; a < p; a++) for (let b = 0; b < p; b++) for (let r = 0; r < cells.length; r++) A[a]![b]! += X[r]![a]! * expected[cells[r]![0]]![cells[r]![1]]! * X[r]![b]!;
  let inv: Matrix; try { inv = inverse(A); } catch { return adjustedResiduals(obs, expected, null); }
  const z = naMatrix(k); cells.forEach(([i, j], r) => { let h = 0; for (let a = 0; a < p; a++) for (let b = 0; b < p; b++) h += X[r]![a]! * inv[a]![b]! * X[r]![b]! * expected[i]![j]!;
    const d = expected[i]![j]! * (1 - h); if (Number.isFinite(d) && d > 0) z[i]![j] = (obs[i]![j]! - expected[i]![j]!) / Math.sqrt(d); }); return z;
}
function inverse(a: Matrix): Matrix { const n = a.length, aug = a.map((r, i) => [...r, ...Array.from({ length: n }, (_, j) => i === j ? 1 : 0)]);
  for (let c = 0; c < n; c++) { let p = c; for (let r = c + 1; r < n; r++) if (Math.abs(aug[r]![c]!) > Math.abs(aug[p]![c]!)) p = r; if (Math.abs(aug[p]![c]!) < 1e-12) throw new Error('singular'); [aug[c], aug[p]] = [aug[p]!, aug[c]!]; const q = aug[c]![c]!; aug[c] = aug[c]!.map((v) => v / q); for (let r = 0; r < n; r++) if (r !== c) { const f = aug[r]![c]!; aug[r] = aug[r]!.map((v, j) => v - f * aug[c]![j]!); } } return aug.map((r) => r.slice(n)); }
function matrixRank(a: Matrix, tolerance = 1e-10): number { const x = cloneMatrix(a); let rank = 0; for (let c = 0; c < (x[0]?.length ?? 0) && rank < x.length; c++) { let p = rank; for (let r = rank + 1; r < x.length; r++) if (Math.abs(x[r]![c]!) > Math.abs(x[p]![c]!)) p = r; if (Math.abs(x[p]![c]!) <= tolerance) continue; [x[rank], x[p]] = [x[p]!, x[rank]!]; for (let r = rank + 1; r < x.length; r++) { const f = x[r]![c]! / x[rank]![c]!; for (let j = c; j < x[r]!.length; j++) x[r]![j]! -= f * x[rank]![j]!; } rank++; } return rank; }
function likelihoodRatio(obs: Matrix, expected: Matrix, structure: Matrix | null) { let statistic = 0; for (let i = 0; i < obs.length; i++) for (let j = 0; j < obs.length; j++) if (obs[i]![j]! > 0 && expected[i]![j]! > 0) statistic += 2 * obs[i]![j]! * Math.log(obs[i]![j]! / expected[i]![j]!);
  let df: number; if (!structure) df = (obs.length - 1) ** 2; else { const cells: Array<[number, number]> = []; for (let i = 0; i < obs.length; i++) for (let j = 0; j < obs.length; j++) if (structure[i]![j] === 1) cells.push([i, j]); const x = cells.map(([i, j]) => [1, ...Array.from({ length: obs.length - 1 }, (_, q) => i === q + 1 ? 1 : 0), ...Array.from({ length: obs.length - 1 }, (_, q) => j === q + 1 ? 1 : 0)]); df = cells.length - matrixRank(x); } return { statistic, df, p: df > 0 ? chiSquareUpper(statistic, df) : NaN }; }

const classical: LSAEngine = (ctx) => {
  const obs = cloneMatrix(ctx.transitions.observed), k = obs.length, n = ctx.transitions.nTransitions; if (!n) throw new Error('No transitions in input.');
  const ipf = ctx.structuralZeros ? lsaIPF(obs, { structure: ctx.structuralZeros }) : null; const expected = ipf?.fit ?? expectedIndependence(obs);
  const z = adjustedResiduals(obs, expected, ctx.structuralZeros), p = z.map((r) => r.map((v) => normalP(v, ctx.alternative))); const totals = ctx.eventTotals ?? rowSums(obs).map((v, i) => Math.max(v, colSums(obs)[i]!)); const ne = ctx.nEvents ?? sum(totals);
  const et = outer(totals, totals, (a, b) => a * b / ne), kap = naMatrix(k), kz = naMatrix(k);
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) { const num = obs[i]![j]! - et[i]![j]!, den = num >= 0 ? Math.min(totals[i]!, totals[j]!) - et[i]![j]! : et[i]![j]!; if (den) kap[i]![j] = num / den; const v = totals[i]! * totals[j]! * (ne - totals[i]!) * (ne - totals[j]!) / (ne ** 2 * (ne - 1)); if (v > 0) kz[i]![j] = num / Math.sqrt(v); }
  return { observed: obs, expected, probability: rowNormalize(obs), adjustedResiduals: z, pValues: p, yulesQ: yulesQ(obs), kappa: kap, kappaZ: kz, kappaP: kz.map((r) => r.map((v) => normalP(v, ctx.alternative))), likelihoodRatio: likelihoodRatio(obs, expected, ctx.structuralZeros), ipf: ipf ? { iterations: ipf.iterations, converged: ipf.converged, maxMarginDifference: ipf.maxMarginDifference } : null, extra: {} };
};
const twoCell: LSAEngine = (ctx) => { if (ctx.structuralZeros) throw new Error("Engine 'two_cell' does not support structural zeros."); const obs = cloneMatrix(ctx.transitions.observed), k = obs.length, n = ctx.transitions.nTransitions, continuity = Number(ctx.params.continuity ?? 0.5); if (!n) throw new Error('No transitions in input.'); const rt = rowSums(obs), ct = colSums(obs), expected = expectedIndependence(obs), or = matrix(k,k), logor=matrix(k,k), se=matrix(k,k), z=matrix(k,k);
  for (let i=0;i<k;i++) for(let j=0;j<k;j++){let a=obs[i]![j]!,b=rt[i]!-a,c=ct[j]!-a,d=n-rt[i]!-ct[j]!+a; if(a===0||b===0||c===0||d===0){a+=continuity;b+=continuity;c+=continuity;d+=continuity;} or[i]![j]=a*d/(b*c);logor[i]![j]=Math.log(or[i]![j]!);se[i]![j]=Math.sqrt(1/a+1/b+1/c+1/d);z[i]![j]=Number.isFinite(logor[i]![j]!/se[i]![j]!)?logor[i]![j]!/se[i]![j]!:NaN;}
  return baseResult(obs,expected,z,ctx,{odds_ratio:or,log_or:logor,log_or_se:se,continuity}); };
const bidirectional: LSAEngine = (ctx) => { noStructural(ctx,'bidirectional'); const obs=cloneMatrix(ctx.transitions.observed),k=obs.length;if(!ctx.transitions.nTransitions)throw new Error('No transitions in input.');const tr=transpose(obs),w=obs.map((r,i)=>r.map((v,j)=>v+tr[i]![j]!)),rt=rowSums(w),n=sum(rt),expected=outer(rt,rt,(a,b)=>a*b/n),z=matrix(k,k,NaN);for(let i=0;i<k;i++)for(let j=0;j<k;j++){const d=expected[i]![j]!*(1-rt[i]!/n)*(1-rt[j]!/n);if(d>0)z[i]![j]=(w[i]![j]!-expected[i]![j]!)/Math.sqrt(d);}return baseResult(obs,expected,z,ctx,{symmetric_obs:w,symmetric_exp:expected,marginals:rt},yulesQ(w));};
const parallel: LSAEngine = (ctx) => dominance(ctx,true);
const nonparallel: LSAEngine = (ctx) => dominance(ctx,false);
function dominance(ctx: LSAEngineContext, useExpected: boolean): LSAEngineResult { noStructural(ctx,useExpected?'parallel_dominance':'nonparallel_dominance'); const obs=cloneMatrix(ctx.transitions.observed),k=obs.length,n=ctx.transitions.nTransitions;if(!n)throw new Error('No transitions in input.');const expected=expectedIndependence(obs),z=matrix(k,k,NaN),dom=matrix(k,k),pair=matrix(k,k),bin=matrix(k,k,NaN);for(let i=0;i<k;i++)for(let j=0;j<k;j++){dom[i]![j]=obs[i]![j]!-obs[j]![i]!;pair[i]![j]=obs[i]![j]!+obs[j]![i]!;const vv=useExpected?expected[i]![j]!+expected[j]![i]!:pair[i]![j]!;if(vv>0)z[i]![j]=dom[i]![j]!/Math.sqrt(vv);if(i===j)z[i]![j]=0;if(!useExpected&&i!==j&&pair[i]![j]!>0)bin[i]![j]=binomialP(obs[i]![j]!,pair[i]![j]!,ctx.alternative);}return baseResult(obs,expected,z,ctx,useExpected?{dominance:dom,dominance_se:pair.map((r,i)=>r.map((_,j)=>Math.sqrt(expected[i]![j]!+expected[j]![i]!)))}:{dominance:dom,pair_totals:pair,binomial_p:bin});}
function noStructural(ctx: LSAEngineContext,name:string){if(ctx.structuralZeros)throw new Error(`Engine '${name}' does not support structural zeros.`);}
function baseResult(obs:Matrix,expected:Matrix,z:Matrix,ctx:LSAEngineContext,extra:Record<string,Matrix|number|number[]>,q=yulesQ(obs)):LSAEngineResult{const k=obs.length,na=naMatrix(k);return{observed:obs,expected,probability:rowNormalize(obs),adjustedResiduals:z,pValues:z.map(r=>r.map(v=>normalP(v,ctx.alternative))),yulesQ:q,kappa:na,kappaZ:cloneMatrix(na),kappaP:cloneMatrix(na),likelihoodRatio:null,ipf:null,extra};}

const registry = new Map<string,LSAEngineEntry>();
export function registerLSAEngine(name:string,fn:LSAEngine,description:string,requires:string[]=[]):string{if(!name||typeof fn!=='function')throw new Error('A name and engine function are required.');registry.set(name,{name,fn,description,requires:[...requires]});return name;}
export function getLSAEngine(name:string):LSAEngineEntry{const e=registry.get(name);if(!e)throw new Error(`Engine '${name}' is not registered. Available engines: ${[...registry.keys()].join(', ')}`);return e;}
export function listLSAEngines():Array<Omit<LSAEngineEntry,'fn'>>{return[...registry.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(({fn:_,...e})=>e);}
export function unregisterLSAEngine(name:string):void{if(!registry.delete(name))throw new Error(`Engine '${name}' is not registered.`);}
registerLSAEngine('classical',classical,'Classical adjusted-residual lag sequential analysis');registerLSAEngine('two_cell',twoCell,'Per-cell 2 x 2 odds-ratio tests');registerLSAEngine('bidirectional',bidirectional,'Symmetric matched-pair analysis');registerLSAEngine('parallel_dominance',parallel,'Expected-count directional dominance');registerLSAEngine('nonparallel_dominance',nonparallel,'Observed-pair directional dominance');
