import { SeededRNG } from '../core/rng.js';
import type { TransferEntropyOptions, TransferEntropyRow } from './types.js';

type Value = string | number | null | undefined;
type SequenceInput = Value[] | Value[][];
interface Triple { future:string; history:string; source:string; }
const sequences=(x:SequenceInput):Value[][]=>Array.isArray(x[0])?x as Value[][]:[x as Value[]];
const entropy=(...cols:string[][]):number=>{const n=cols[0]?.length??0;if(!n)return NaN;const counts=new Map<string,number>();for(let i=0;i<n;i++){const key=cols.map(c=>c[i]).join('\0');counts.set(key,(counts.get(key)??0)+1);}let h=0;for(const c of counts.values()){const p=c/n;h-=p*Math.log2(p);}return h;};
function triples(source:Value[],target:Value[],lag:number,history:number):Triple[]{const out:Triple[]=[];for(let t=history-1;t+lag<target.length;t++){const f=target[t+lag],s=source[t],hist=Array.from({length:history},(_,d)=>target[t-d]);if(f==null||f===''||s==null||s===''||hist.some(v=>v==null||v===''))continue;out.push({future:String(f),history:hist.map(String).join('|'),source:String(s)});}return out;}
function value(rows:Triple[]):{te:number;leftover:number}{const f=rows.map(r=>r.future),h=rows.map(r=>r.history),s=rows.map(r=>r.source),leftover=entropy(f,h)-entropy(h),conditional=entropy(f,s,h)-entropy(s,h);return{te:leftover-conditional,leftover};}
function one(source:Value[][],target:Value[][],options:Required<Pick<TransferEntropyOptions,'lag'|'history'|'test'|'iterations'>>,rng:SeededRNG):Omit<TransferEntropyRow,'from'|'to'>{const rows=source.flatMap((s,i)=>triples(s,target[i]!,options.lag,options.history));if(!rows.length)return{te:NaN,teEffective:NaN,teNormalized:NaN,p:NaN,n:0};const v=value(rows);if(options.test==='none')return{te:v.te,teNormalized:v.leftover>0?v.te/v.leftover:NaN,n:rows.length};const sur=Array.from({length:options.iterations},()=>{const src=rng.shuffle(rows.map(r=>r.source).slice());return value(rows.map((r,i)=>({...r,source:src[i]!}))).te;});return{te:v.te,teEffective:v.te-sur.reduce((a,b)=>a+b,0)/sur.length,teNormalized:v.leftover>0?v.te/v.leftover:NaN,p:(1+sur.filter(x=>x>=v.te).length)/(1+sur.length),n:rows.length};}
export function transferEntropy(x:SequenceInput,y?:SequenceInput|null,options:TransferEntropyOptions={}):TransferEntropyRow[]{const lag=options.lag??1,history=options.history??1,iterations=options.iterations??199,test=options.test??'surrogate';if(!Number.isInteger(lag)||lag<1||!Number.isInteger(history)||history<1||!Number.isInteger(iterations)||iterations<1)throw new Error('lag, history, and iterations must be positive whole numbers.');const rng=new SeededRNG(options.seed??(Date.now()&0xffffffff)),xs=sequences(x),opts={lag,history,iterations,test},out:TransferEntropyRow[]=[];
  if(y){const ys=sequences(y);if(xs.length!==ys.length||xs.some((s,i)=>s.length!==ys[i]!.length))throw new Error('x and y must contain aligned sequences of equal lengths.');out.push({from:options.xLabel??'x',to:options.yLabel??'y',...one(xs,ys,opts,rng)},{from:options.yLabel??'y',to:options.xLabel??'x',...one(ys,xs,opts,rng)});
  }else{const states=[...new Set(xs.flat().filter(v=>v!=null&&v!=='').map(String))].sort();const indicator=(s:string)=>xs.map(seq=>seq.map(v=>v==null||v===''?null:(String(v)===s?'1':'0')));for(const from of states)for(const to of states)if(from!==to)out.push({from,to,...one(indicator(from),indicator(to),opts,rng)});}
  if(options.normalize===false)for(const r of out)delete r.teNormalized;if(test==='none')for(const r of out){delete r.teEffective;delete r.p;}return out.sort((a,b)=>b.te-a.te);}
