import { SeededRNG } from '../core/rng.js';
import type { LSABayesCompareOptions, LSABayesComparison, LSABayesPairwiseComparison, LSACompareMeasure, LSACompareOptions, LSAComparison, LSAComparisonEdge, LSAFit, LSAGroup, LSAPairwiseComparison, Matrix } from './types.js';
import { lsa } from './fit.js';
import { flattenColumnMajor, matrix, mean, quantile7 } from './math.js';

function resolve(x:LSAFit|LSAGroup,y?:LSAFit):{fits:LSAFit[];names:string[]}{if(x.kind==='lsa_group'){if(y)throw new Error('Do not supply y with an LSA group.');if(x.levels.length<2)throw new Error('At least two groups are required.');return{fits:x.levels.map(g=>x.groups[g]!),names:x.levels};}if(!y)throw new Error('Supply either an LSA group or two LSA fits.');return{fits:[x,y],names:['a','b']};}
function validate(fits:LSAFit[]):void{const a=fits[0]!;for(const f of fits){if(f.data.source!=='events')throw new Error('Comparison requires event-level fits.');if(f.method!==a.method||f.params.lag!==a.params.lag||f.data.labels.join('\0')!==a.data.labels.join('\0'))throw new Error('Compared fits must share engine, lag, and labels.');}}
function refit(base:LSAFit,seqs:number[][]):LSAFit{return lsa(seqs.map(s=>s.map(v=>v+1)),{...base.params,labels:base.data.labels,group:null}) as LSAFit;}
function logOR(f:LSAFit):Matrix{const o=f.observed,k=o.length,rt=o.map(r=>r.reduce((s,v)=>s+v,0)),ct=Array.from({length:k},(_,j)=>o.reduce((s,r)=>s+r[j]!,0)),n=rt.reduce((s,v)=>s+v,0),out=matrix(k,k,NaN);for(let i=0;i<k;i++)for(let j=0;j<k;j++){if(!Number.isFinite(f.adjustedResiduals[i]![j]!))continue;let a=o[i]![j]!,b=rt[i]!-a,c=ct[j]!-a,d=n-rt[i]!-ct[j]!+a;if(a===0||b===0||c===0||d===0){a+=.5;b+=.5;c+=.5;d+=.5;}out[i]![j]=Math.log(a*d/(b*c));}return out;}
function measure(f:LSAFit,m:LSACompareMeasure):Matrix{if(m==='prob')return f.probability;if(m==='adj_res')return f.adjustedResiduals;if(m==='yules_q')return f.yulesQ;if(m==='count')return f.observed;if(m==='log_or')return logOR(f);return f.observed.map((r,i)=>r.map((v,j)=>f.expected[i]![j]!>0?v/f.expected[i]![j]!:NaN));}
function adjustP(values:number[],method:string):number[]{const out=values.slice(),idx=values.map((p,i)=>({p,i})).filter(x=>Number.isFinite(x.p));const n=idx.length;if(method==='none')return out;if(method==='bonferroni'){for(const x of idx)out[x.i]=Math.min(1,x.p*n);return out;}idx.sort((a,b)=>a.p-b.p);if(method==='holm'){let mx=0;idx.forEach((x,k)=>{mx=Math.max(mx,x.p*(n-k));out[x.i]=Math.min(1,mx);});return out;}const c=method==='BY'?Array.from({length:n},(_,i)=>1/(i+1)).reduce((a,b)=>a+b,0):1;let mn=1;for(let k=n-1;k>=0;k--){const x=idx[k]!;mn=Math.min(mn,x.p*n*c/(k+1));out[x.i]=Math.min(1,mn);}return out;}

export function compareLSA(x:LSAFit|LSAGroup,y?:LSAFit,options:LSACompareOptions={}):LSAComparison|LSAPairwiseComparison{const r=resolve(x,y);validate(r.fits);if(r.fits.length===2)return compareTwo(r.fits[0]!,r.fits[1]!,[r.names[0]!,r.names[1]!],options);const comparisons:Record<string,LSAComparison>={},edges:Array<LSAComparisonEdge&{groupA:string;groupB:string}>=[];for(let i=0;i<r.fits.length;i++)for(let j=i+1;j<r.fits.length;j++){const c=compareTwo(r.fits[i]!,r.fits[j]!,[r.names[i]!,r.names[j]!],{...options,adjust:'none'}),key=`${r.names[i]}_vs_${r.names[j]}`;comparisons[key]=c;edges.push(...c.edges.map(e=>({...e,groupA:r.names[i]!,groupB:r.names[j]!})));}const adj=adjustP(edges.map(e=>e.p),options.adjust??'none');edges.forEach((e,i)=>{e.pAdjusted=adj[i]!;e.significant=Number.isFinite(adj[i]!)&&adj[i]!<r.fits[0]!.params.alpha;});return{kind:'lsa_comparison_pairwise',comparisons,edges};}
function compareTwo(a:LSAFit,b:LSAFit,names:[string,string],options:LSACompareOptions):LSAComparison{const iterations=options.iterations??1000,m=options.measure??'log_or',minCount=options.minCount??5,rng=new SeededRNG(options.seed??(Date.now()&0xffffffff)),sa=a.data.sequences!,sb=b.data.sequences!,pooled=[...sa,...sb],nA=sa.length,ma=flattenColumnMajor(measure(a,m)),mb=flattenColumnMajor(measure(b,m)),observed=ma.map((v,i)=>v-mb[i]!),nulls=Array.from({length:iterations},()=>{const p=rng.permutation(pooled.length),fa=refit(a,p.slice(0,nA).map(i=>pooled[i]!)),fb=refit(a,p.slice(nA).map(i=>pooled[i]!)),aa=flattenColumnMajor(measure(fa,m)),bb=flattenColumnMajor(measure(fb,m));return aa.map((v,i)=>v-bb[i]!);});const counts=flattenColumnMajor(a.observed).map((v,i)=>v+flattenColumnMajor(b.observed)[i]!),p=observed.map((v,i)=>{if(!Number.isFinite(v)||counts[i]!<minCount)return NaN;const z=nulls.map(r=>r[i]!).filter(Number.isFinite);return z.length?(1+z.filter(x=>Math.abs(x)>=Math.abs(v)).length)/(1+z.length):NaN;}),padj=adjustP(p,options.adjust??'none'),edges=a.edges.map((e,i)=>({from:e.from,to:e.to,valueA:ma[i]!,valueB:mb[i]!,diff:observed[i]!,p:p[i]!,pAdjusted:padj[i]!,significant:Number.isFinite(padj[i]!)&&padj[i]!<a.params.alpha}));return{kind:'lsa_comparison',edges,fits:[a,b],groups:names,iterations,measure:m};}

function normal(rng:SeededRNG):number{const u=Math.max(Number.MIN_VALUE,rng.random()),v=rng.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}
function gamma(shape:number,rng:SeededRNG):number{if(shape<1)return gamma(shape+1,rng)*rng.random()**(1/shape);const d=shape-1/3,c=1/Math.sqrt(9*d);while(true){let x=normal(rng),v=1+c*x;if(v<=0)continue;v=v**3;const u=rng.random();if(u<1-.0331*x**4||Math.log(u)<.5*x*x+d*(1-v+Math.log(v)))return d*v;}}
const beta=(a:number,b:number,rng:SeededRNG)=>{const x=gamma(a,rng),y=gamma(b,rng);return x/(x+y);};
export function bayesCompareLSA(x:LSAFit|LSAGroup,y?:LSAFit,options:LSABayesCompareOptions={}):LSABayesComparison|LSABayesPairwiseComparison{const r=resolve(x,y);validate(r.fits);if(r.fits.length===2)return bayesTwo(r.fits[0]!,r.fits[1]!,[r.names[0]!,r.names[1]!],options);const comparisons:Record<string,LSABayesComparison>={},edges:Array<LSAComparisonEdge&{groupA:string;groupB:string}>=[];for(let i=0;i<r.fits.length;i++)for(let j=i+1;j<r.fits.length;j++){const c=bayesTwo(r.fits[i]!,r.fits[j]!,[r.names[i]!,r.names[j]!],options);comparisons[`${r.names[i]}_vs_${r.names[j]}`]=c;edges.push(...c.edges.map(e=>({...e,groupA:r.names[i]!,groupB:r.names[j]!})));}const adj=adjustP(edges.map(e=>e.p),options.adjust??'none');edges.forEach((e,i)=>e.pAdjusted=adj[i]!);return{kind:'lsa_bayes_pairwise',comparisons,edges,draws:options.draws??10000,prior:options.prior??.5};}
function bayesTwo(a:LSAFit,b:LSAFit,names:[string,string],options:LSABayesCompareOptions):LSABayesComparison{const prior=options.prior??.5,draws=options.draws??10000,ci=options.confidenceLevel??.95,meanThreshold=options.meanThreshold??.01,boundThreshold=options.boundThreshold??.001,rng=new SeededRNG(options.seed??(Date.now()&0xffffffff)),tail=(1-ci)/2,rawP:number[]=[],temp:Array<LSAComparisonEdge&Record<string,number|boolean|string>>=[];a.edges.forEach((e,idx)=>{const i=e.fromId-1,j=e.toId-1,aa=a.observed[i]![j]!+prior,ab=b.observed[i]![j]!+prior,ta=a.observed[i]!.reduce((s,v)=>s+v+prior,0),tb=b.observed[i]!.reduce((s,v)=>s+v+prior,0),pa=aa/ta,pb=ab/tb,dd=Array.from({length:draws},()=>beta(aa,ta-aa,rng)-beta(ab,tb-ab,rng)),diff=pa-pb,low=quantile7(dd,tail),high=quantile7(dd,1-tail),pos=dd.filter(v=>v>0).length/draws,pd=Math.max(pos,1-pos),p=2*(1-pd),sd=Math.sqrt(Math.max(0,mean(dd.map(v=>v*v))-mean(dd)**2)),valid=Number.isFinite(e.prob)&&Number.isFinite(b.edges[idx]!.prob)&&a.params.structuralZeros?.[i]?.[j]!==0,sig=valid&&(low>0||high<0)&&Math.abs(diff)>meanThreshold&&Math.min(Math.abs(low),Math.abs(high))>boundThreshold;rawP.push(valid?p:NaN);temp.push({from:e.from,to:e.to,valueA:pa,valueB:pb,diff,p:valid?p:NaN,pAdjusted:NaN,significant:sig,ciLow:low,ciHigh:high,pd,effectSize:Number.isFinite(diff/sd)?diff/sd:0});});const adj=adjustP(rawP,options.adjust??'none');temp.forEach((e,i)=>e.pAdjusted=adj[i]!);return{kind:'lsa_bayes',edges:temp,fits:[a,b],groups:names,draws,prior};}
