import type {
  LSABayesComparison, LSABayesPairwiseComparison, LSABootstrapEdge,
  LSABootstrapResult, LSACertaintyEdge, LSACertaintyResult, LSAComparison,
  LSAFit, LSAGroup, LSAPlotOptions, LSAPairwiseComparison, Matrix,
} from './types.js';
import { cleanWeight } from './fit.js';

// These are the canonical lagdynamics palettes. They intentionally match the
// R package's ggplot/cograph views rather than introducing a JS-only theme.
const DIV_LOW = '#2166AC';
const DIV_MID = '#F7F7F7';
const DIV_HIGH = '#B2182B';
const SEQ_LOW = '#DEEBF7';
const SEQ_HIGH = '#08519C';
const CMP_LOW = '#D33F6A';
const CMP_MID = '#F7F7F7';
const CMP_HIGH = '#4A6FE3';
const GREY_85 = '#D9D9D9';
const TNA_COLORS = [
  '#4e79a7', '#f28e2b', '#e15759', '#76b7b2', '#59a14f',
  '#edc948', '#b07aa1', '#ff9da7', '#9c755f',
];
const CHORD_COLORS = [
  '#E53935', '#8E24AA', '#1E88E5', '#00897B', '#43A047', '#FFB300',
  '#F4511E', '#00ACC1', '#6D4C41', '#D81B60', '#3949AB', '#7CB342',
];

const esc = (value: unknown): string => String(value).replace(
  /[&<>"']/g,
  c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!,
);
const clamp = (value: number, lo = 0, hi = 1): number => Math.max(lo, Math.min(hi, value));
const fmt = (value: number, digits = 2): string => Number.isFinite(value) ? value.toFixed(digits) : '';
const sum = (values: number[]): number => values.reduce((total, value) => total + value, 0);
function parseHex(hex: string): [number, number, number] {
  const h = hex.replace('#', '');
  return [0, 2, 4].map(i => Number.parseInt(h.slice(i, i + 2), 16)) as [number, number, number];
}

function mix(a: string, b: string, t: number): string {
  const x = parseHex(a), y = parseHex(b), u = clamp(t);
  return `#${x.map((v, i) => Math.round(v + (y[i]! - v) * u).toString(16).padStart(2, '0')).join('')}`;
}

function divergingColor(value: number, limit: number, low = DIV_LOW, mid = DIV_MID, high = DIV_HIGH): string {
  if (!Number.isFinite(value)) return GREY_85;
  const z = clamp(value / (limit || 1), -1, 1);
  return z < 0 ? mix(mid, low, -z) : mix(mid, high, z);
}

function sequentialColor(value: number, min: number, max: number): string {
  if (!Number.isFinite(value)) return GREY_85;
  return mix(SEQ_LOW, SEQ_HIGH, (value - min) / (max - min || 1));
}

let svgCounter = 0;
function frame(
  body: string,
  options: LSAPlotOptions,
  title: string,
  subtitle = '',
  centered = false,
): string {
  const width = options.width ?? 760;
  const height = options.height ?? 560;
  const x = centered ? width / 2 : 28;
  const anchor = centered ? 'middle' : 'start';
  return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(options.title ?? title)}" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">
<rect width="100%" height="100%" fill="${options.background ?? '#ffffff'}"/>
<style>
text{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;fill:#333}
.title{font-size:18px;font-weight:700}.subtitle{font-size:10px;fill:#666}.axis{font-size:11px;fill:#333}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.small{font-size:9px}.tiny{font-size:8px}.halo{paint-order:stroke;stroke:#fff;stroke-width:3px;stroke-linejoin:round}
</style>
<text class="title" x="${x}" y="28" text-anchor="${anchor}">${esc(options.title ?? title)}</text>
${(options.subtitle ?? subtitle) ? `<text class="subtitle" x="${x}" y="46" text-anchor="${anchor}">${esc(options.subtitle ?? subtitle)}</text>` : ''}
${body}</svg>`;
}

function colorLegend(
  id: string,
  x: number,
  y: number,
  height: number,
  label: string,
  min: number,
  max: number,
  diverging: boolean,
  low = DIV_LOW,
  high = DIV_HIGH,
): string {
  const mid = diverging ? DIV_MID : mix(low, high, 0.5);
  return `<defs><linearGradient id="${id}" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="${low}"/><stop offset=".5" stop-color="${mid}"/><stop offset="1" stop-color="${high}"/></linearGradient></defs>
<rect x="${x}" y="${y}" width="12" height="${height}" rx="1" fill="url(#${id})"/>
<text class="tiny" x="${x + 18}" y="${y + 4}">${fmt(max, 1)}</text><text class="tiny" x="${x + 18}" y="${y + height}">${fmt(min, 1)}</text>
<text class="small" x="${x - 2}" y="${y - 8}">${esc(label)}</text>`;
}

function arcPath(cx: number, cy: number, inner: number, outer: number, start: number, end: number): string {
  const p = (radius: number, angle: number): [number, number] => [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  const a = p(outer, start), b = p(outer, end), c = p(inner, end), d = p(inner, start);
  const large = Math.abs(end - start) > Math.PI ? 1 : 0;
  const sweep = end >= start ? 1 : 0;
  return `M${a[0]} ${a[1]} A${outer} ${outer} 0 ${large} ${sweep} ${b[0]} ${b[1]} L${c[0]} ${c[1]} A${inner} ${inner} 0 ${large} ${sweep ? 0 : 1} ${d[0]} ${d[1]} Z`;
}

function tangential(angle: number): number {
  const degrees = ((angle * 180 / Math.PI) % 360 + 360) % 360;
  const rotation = degrees + 90;
  return degrees > 90 && degrees < 270 ? rotation + 180 : rotation;
}

export interface HeatmapOptions extends LSAPlotOptions {
  which?: 'residuals' | 'prob' | 'count' | 'expected';
}

/** Exact browser counterpart of lagdynamics' ggplot heatmap contract. */
export function plotLSAHeatmap(fit: LSAFit, options: HeatmapOptions = {}): string {
  const which = options.which ?? 'residuals';
  const matrix = which === 'residuals' ? fit.adjustedResiduals
    : which === 'prob' ? fit.probability
      : which === 'count' ? fit.observed : fit.expected;
  const width = options.width ?? 760, height = options.height ?? 560;
  const left = 138, top = 72, right = 112, bottom = 92;
  const n = fit.data.nStates;
  const cell = Math.min((width - left - right) / n, (height - top - bottom) / n);
  const plotWidth = cell * n, plotHeight = cell * n;
  const outgoing = fit.observed.map(row => sum(row));
  const rowOrder = Array.from({ length: n }, (_, i) => i).sort((a, b) => outgoing[b]! - outgoing[a]!);
  const finite = matrix.flat().filter(Number.isFinite);
  const limit = Math.max(1e-12, ...finite.map(v => which === 'residuals' ? Math.abs(v) : v));
  const min = which === 'prob' ? 0 : Math.min(0, ...finite);
  const title = ({ residuals: 'Adjusted residuals', prob: 'Transition probabilities', count: 'Observed counts', expected: 'Expected counts' } as const)[which];
  const caption = which === 'residuals'
    ? 'warm over-represented, cool avoided; significant cells bold'
    : which === 'prob' ? 'P(to | from); modal next state bold' : 'modal next state bold';
  const subtitle = `${fit.method} engine, lag ${fit.params.lag} · ${sum(fit.observed.flat())} transitions · ${caption}`;
  const id = `ld-heat-${++svgCounter}`;
  let body = '';

  for (let row = 0; row < n; row++) {
    const i = rowOrder[row]!;
    const rank = matrix[i]!.map((v, j) => fit.observed[i]![j] === 0 || !Number.isFinite(v) ? -Infinity : (which === 'residuals' ? Math.abs(v) : v));
    const salient = rank.indexOf(Math.max(...rank));
    body += `<text class="axis mono" text-anchor="end" x="${left - 9}" y="${top + (row + .62) * cell}">${esc(fit.data.labels[i])}</text>`;
    for (let j = 0; j < n; j++) {
      const raw = matrix[i]![j]!;
      const present = fit.observed[i]![j]! > 0 && Number.isFinite(raw);
      const value = present ? raw : NaN;
      const fill = which === 'residuals' ? divergingColor(value, limit) : sequentialColor(value, min, which === 'prob' ? 1 : limit);
      const bold = present && j === salient && (which !== 'residuals' || fit.edges.find(e => e.fromId === i + 1 && e.toId === j + 1)?.significant);
      const x = left + j * cell, y = top + row * cell;
      body += `<rect x="${x}" y="${y}" width="${cell}" height="${cell}" fill="${fill}" stroke="#fff" stroke-width="1"/>`;
      if (present) {
        body += `<text class="small" text-anchor="middle" x="${x + cell / 2}" y="${y + cell / 2 + 3}" fill="${bold ? '#fff' : '#333'}" font-weight="${bold ? '700' : '400'}">${fmt(raw, which === 'count' ? 0 : 2)}</text>`;
      }
    }
  }
  for (let j = 0; j < n; j++) {
    const x = left + (j + .55) * cell, y = top + plotHeight + 12;
    body += `<text class="axis" text-anchor="end" transform="translate(${x},${y}) rotate(-45)">${esc(fit.data.labels[j])}</text>`;
  }
  body += `<text class="axis" text-anchor="middle" x="${left + plotWidth / 2}" y="${height - 20}">Next state</text>`;
  body += colorLegend(id, left + plotWidth + 30, top + 18, Math.max(90, plotHeight - 36), which === 'residuals' ? 'z' : which === 'prob' ? 'P(to | from)' : which, which === 'residuals' ? -limit : min, which === 'prob' ? 1 : limit, which === 'residuals');
  return frame(body, options, title, subtitle);
}

export interface TransitionPlotOptions extends LSAPlotOptions {
  weights?: 'residuals' | 'tna' | 'relative' | 'count' | 'prob' | 'lift' | 'yules_q';
  top?: number;
  decimals?: number;
  edgeLabels?: boolean;
  edgeCutoff?: number;
  nodeFill?: string;
  /** Minimum rendered edge width in SVG units. Default 0.55. */
  edgeWidthMin?: number;
  /** Maximum rendered edge width in SVG units. Default 2.8. */
  edgeWidthMax?: number;
  /** Arrowhead scale relative to the edge width. Default 1. */
  arrowScale?: number;
}

interface NetworkEdge { i: number; j: number; value: number }

function networkPath(
  source: { x: number; y: number },
  target: { x: number; y: number },
  nodeRadius: number,
  curvature: number,
): { path: string; lx: number; ly: number } {
  const dx = target.x - source.x, dy = target.y - source.y, length = Math.hypot(dx, dy) || 1;
  const ux = dx / length, uy = dy / length, px = -uy, py = ux;
  const mx = (source.x + target.x) / 2 + px * curvature;
  const my = (source.y + target.y) / 2 + py * curvature;
  const sdx = mx - source.x, sdy = my - source.y, sl = Math.hypot(sdx, sdy) || 1;
  const edx = target.x - mx, edy = target.y - my, el = Math.hypot(edx, edy) || 1;
  const sx = source.x + sdx / sl * nodeRadius, sy = source.y + sdy / sl * nodeRadius;
  const tx = target.x - edx / el * (nodeRadius + 8), ty = target.y - edy / el * (nodeRadius + 8);
  const t = .52;
  const lx = (1 - t) ** 2 * sx + 2 * (1 - t) * t * mx + t ** 2 * tx;
  const ly = (1 - t) ** 2 * sy + 2 * (1 - t) * t * my + t ** 2 * ty;
  return { path: `M${sx} ${sy} Q${mx} ${my} ${tx} ${ty}`, lx, ly };
}

/**
 * Exact SVG translation of cograph::draw_self_loop_base().
 *
 * cograph draws an open circle whose centre is one node radius away from the
 * node centre and whose radius is 0.8 node radii. The visible arc begins and
 * ends where that circle intersects the node boundary; the far-side arc is
 * retained and its end tangent carries the arrowhead.
 */
function cographSelfLoop(
  x: number,
  y: number,
  nodeRadius: number,
  rotation: number,
): { path: string; labelX: number; labelY: number } {
  const loopRadius = nodeRadius * .8;
  const loopDistance = nodeRadius;
  const anchorRadius = nodeRadius;
  const loopX = x + loopDistance * Math.cos(rotation);
  const loopY = y + loopDistance * Math.sin(rotation);
  const cosine = clamp(
    (loopDistance ** 2 + loopRadius ** 2 - anchorRadius ** 2)
      / (2 * loopDistance * loopRadius),
    -1,
    1,
  );
  const alpha = Math.acos(cosine);
  const start = rotation + Math.PI + alpha;
  const end = rotation + Math.PI - alpha + 2 * Math.PI;
  const startX = loopX + loopRadius * Math.cos(start);
  const startY = loopY + loopRadius * Math.sin(start);
  const endX = loopX + loopRadius * Math.cos(end);
  const endY = loopY + loopRadius * Math.sin(end);
  return {
    path: `M${startX} ${startY} A${loopRadius} ${loopRadius} 0 1 1 ${endX} ${endY}`,
    labelX: x + nodeRadius * 2.5 * Math.cos(rotation),
    labelY: y + nodeRadius * 2.5 * Math.sin(rotation),
  };
}

/** TNA/cograph-style transition network, adapted to a self-contained SVG. */
export function plotTransitions(fit: LSAFit, options: TransitionPlotOptions = {}): string {
  const key = options.weights ?? 'residuals';
  const metric = key === 'residuals' ? 'adj_res' : key === 'tna' || key === 'relative' ? 'prob' : key;
  const matrix = cleanWeight(fit, metric as 'prob' | 'count' | 'adj_res' | 'yules_q' | 'lift');
  const tnaStyled = metric === 'prob' || metric === 'count';
  const signed = metric === 'adj_res' || metric === 'yules_q';
  const cutoff = options.edgeCutoff ?? (metric === 'prob' ? .05 : 0);
  const edges: NetworkEdge[] = [];
  for (let i = 0; i < matrix.length; i++) for (let j = 0; j < matrix.length; j++) {
    const value = matrix[i]![j]!;
    if (!Number.isFinite(value) || Math.abs(value) <= cutoff) continue;
    if (options.significant && !(fit.pValues[i]![j]! < fit.params.alpha)) continue;
    edges.push({ i, j, value });
  }
  if (options.top !== undefined) {
    const keep = options.top < 1 ? Math.ceil(edges.length * options.top) : Math.min(edges.length, Math.floor(options.top));
    edges.sort((a, b) => Math.abs(b.value) - Math.abs(a.value)).splice(keep);
  }
  const width = options.width ?? 760, height = options.height ?? 560;
  const cx = width / 2, cy = height / 2 + 12, radius = Math.min(width, height) * .31, nodeRadius = 23;
  // TNA nodes add a 5-unit initial-probability ring centred at r + 4.
  // Its true painted boundary is therefore r + 6.5. Edges and loops must
  // anchor to that visible boundary, not to the inner coloured disc.
  const visibleNodeRadius = tnaStyled ? nodeRadius + 6.5 : nodeRadius;
  const positions = fit.data.labels.map((_, i) => {
    const angle = -Math.PI / 2 + 2 * Math.PI * i / fit.data.nStates;
    return { x: cx + radius * Math.cos(angle), y: cy + radius * Math.sin(angle) };
  });
  const pairSet = new Set(edges.map(e => `${e.i}-${e.j}`));
  const max = Math.max(1e-12, ...edges.map(e => Math.abs(e.value)));
  const edgeWidthMin = Math.max(.1, options.edgeWidthMin ?? .55);
  const edgeWidthMax = Math.max(edgeWidthMin, options.edgeWidthMax ?? 2.8);
  const arrowScale = Math.max(.25, options.arrowScale ?? 1);
  const marker = `ld-arrow-${++svgCounter}`;
  let body = '<defs>';
  // Marker size follows the constrained stroke scale. Defining a short set
  // avoids a giant fixed arrowhead on thin edges while keeping SVG output
  // portable (context-stroke is still used for the edge colour).
  for (let level = 0; level < 4; level++) {
    const markerSize = (3.8 + level * .75) * arrowScale;
    body += `<marker id="${marker}-${level}" viewBox="0 0 7 6" refX="6.3" refY="3" markerWidth="${markerSize}" markerHeight="${markerSize * .86}" orient="auto" markerUnits="userSpaceOnUse"><path d="M0 0 L7 3 L0 6 Z" fill="context-stroke"/></marker>`;
  }
  body += '</defs>';

  for (const edge of edges.slice().sort((a, b) => Math.abs(a.value) - Math.abs(b.value))) {
    const source = positions[edge.i]!, target = positions[edge.j]!;
    const positiveColor = tnaStyled ? '#2B4C7E' : signed ? CMP_HIGH : '#4A6FA5';
    const color = edge.value < 0 && signed ? CMP_LOW : positiveColor;
    // Square-root scaling preserves visible differences without allowing one
    // large edge to turn into a band. The final width is strictly bounded.
    const strength = Math.sqrt(clamp(Math.abs(edge.value) / max));
    const strokeWidth = edgeWidthMin + (edgeWidthMax - edgeWidthMin) * strength;
    const markerLevel = Math.min(3, Math.floor(strength * 4));
    const markerUrl = `url(#${marker}-${markerLevel})`;
    const dash = edge.value < 0 && signed ? ' stroke-dasharray="7 5"' : '';
    const halo = edge.value < 0 && signed ? Math.abs(edge.value) / max : 0;
    if (edge.i === edge.j) {
      // cograph's default loop rotation points away from the layout centre.
      const rotation = Math.atan2(source.y - cy, source.x - cx);
      const loop = cographSelfLoop(source.x, source.y, visibleNodeRadius, rotation);
      if (halo) body += `<path d="${loop.path}" fill="none" stroke="${CMP_LOW}" stroke-width="${strokeWidth + 2.6 * strength}" stroke-opacity=".13"/>`;
      body += `<path d="${loop.path}" fill="none" stroke="${color}" stroke-width="${strokeWidth}" stroke-opacity=".82" stroke-linecap="round"${dash} marker-end="${markerUrl}"/>`;
      if (options.edgeLabels !== false) body += `<text class="small halo" text-anchor="middle" x="${loop.labelX}" y="${loop.labelY + 3}">${fmt(edge.value, options.decimals ?? 1)}</text>`;
      continue;
    }
    const reverse = pairSet.has(`${edge.j}-${edge.i}`);
    const geometry = networkPath(source, target, visibleNodeRadius, reverse ? 23 : 0);
    if (halo) body += `<path d="${geometry.path}" fill="none" stroke="${CMP_LOW}" stroke-width="${strokeWidth + 2.6 * strength}" stroke-opacity=".13"/>`;
    body += `<path d="${geometry.path}" fill="none" stroke="${color}" stroke-width="${strokeWidth}" stroke-opacity=".78" stroke-linecap="round"${dash} marker-end="${markerUrl}"><title>${esc(fit.data.labels[edge.i])} → ${esc(fit.data.labels[edge.j])}: ${fmt(edge.value, options.decimals ?? 2)}</title></path>`;
    if (options.edgeLabels !== false) body += `<text class="small halo" text-anchor="middle" x="${geometry.lx}" y="${geometry.ly - 3}">${fmt(edge.value, options.decimals ?? 1)}</text>`;
  }

  const palette = options.colors ?? TNA_COLORS;
  positions.forEach((position, i) => {
    const fill = options.nodeFill ?? (tnaStyled ? palette[i % palette.length]! : '#fff');
    if (tnaStyled) {
      const init = clamp(fit.initialProbabilities?.[i] ?? 0);
      const circumference = 2 * Math.PI * (nodeRadius + 4);
      body += `<circle cx="${position.x}" cy="${position.y}" r="${nodeRadius + 4}" fill="none" stroke="#e5e7eb" stroke-width="5"/>`;
      body += `<circle cx="${position.x}" cy="${position.y}" r="${nodeRadius + 4}" fill="none" stroke="${palette[i % palette.length]}" stroke-width="5" stroke-linecap="round" stroke-dasharray="${circumference * init} ${circumference}" transform="rotate(-90 ${position.x} ${position.y})"/>`;
    }
    body += `<circle cx="${position.x}" cy="${position.y}" r="${nodeRadius}" fill="${fill}" stroke="${tnaStyled ? '#999' : 'steelblue'}" stroke-width="${tnaStyled ? 1.5 : 1.1}"/>`;
    body += `<text class="axis halo" font-weight="600" text-anchor="middle" x="${position.x}" y="${position.y + 4}">${esc(fit.data.labels[i])}</text>`;
  });
  const legend = tnaStyled
    ? `${metric === 'prob' ? 'TNA probability network · edges below 0.05 omitted' : 'frequency transition network'} · node ring = initial-state probability`
    : signed ? 'blue solid = over-represented · red dashed + halo = avoided' : 'edge width = lift';
  body += `<text class="subtitle" text-anchor="middle" x="${cx}" y="${height - 18}">${esc(legend)}</text>`;
  return frame(body, options, tnaStyled ? 'Transition network' : signed ? 'Residual network' : 'Lift network');
}

export interface ChordOptions extends LSAPlotOptions {
  compare?: LSAFit;
  widthMetric?: 'count' | 'prob';
  colorMetric?: 'residuals' | 'lift' | 'prob' | 'count';
  selfLoops?: boolean;
  alpha?: number;
}

interface ChordSegment { start: number; end: number; mid: number; flow: number }
interface ChordRibbon { i: number; j: number; fs: number; fe: number; ts: number; te: number; weight: number; colorValue: number }

function chordRibbon(cx: number, cy: number, radius: number, ribbon: ChordRibbon): string {
  const p = (angle: number): [number, number] => [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  const a = p(ribbon.fs), b = p(ribbon.fe), c = p(ribbon.ts), d = p(ribbon.te);
  return `M${a[0]} ${a[1]} A${radius} ${radius} 0 0 1 ${b[0]} ${b[1]} Q${cx} ${cy} ${c[0]} ${c[1]} A${radius} ${radius} 0 0 1 ${d[0]} ${d[1]} Q${cx} ${cy} ${a[0]} ${a[1]} Z`;
}

/** cograph plot_chord geometry: flow-sized ring segments and weighted ribbons. */
export function plotChords(fit: LSAFit, options: ChordOptions = {}): string {
  const widthMetric = options.widthMetric ?? 'count';
  const colorMetric = options.colorMetric ?? 'residuals';
  const widths = cleanWeight(fit, widthMetric);
  const colorKey = colorMetric === 'residuals' ? 'adj_res' : colorMetric;
  const colors = cleanWeight(fit, colorKey as 'adj_res' | 'lift' | 'prob' | 'count');
  const compare = options.compare ? cleanWeight(options.compare, colorKey as 'adj_res' | 'lift' | 'prob' | 'count') : null;
  const n = fit.data.nStates;
  if (options.significant && !compare) for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (!(fit.pValues[i]![j]! < fit.params.alpha)) widths[i]![j] = 0;
  if (options.selfLoops === false) for (let i = 0; i < n; i++) widths[i]![i] = 0;
  const outgoing = widths.map(row => sum(row.map(Math.abs)));
  const incoming = Array.from({ length: n }, (_, j) => sum(widths.map(row => Math.abs(row[j]!))));
  const flows = outgoing.map((value, i) => value + incoming[i]! - Math.abs(widths[i]![i]!));
  const totalFlow = sum(flows) || n;
  const pad = .02, available = 2 * Math.PI - n * pad;
  let cursor = -Math.PI / 2;
  const segments: ChordSegment[] = flows.map(flow => {
    const span = available * (flow || totalFlow * .01 / n) / totalFlow;
    const segment = { start: cursor, end: cursor + span, mid: cursor + span / 2, flow };
    cursor += span + pad;
    return segment;
  });
  const outCursor = segments.map(s => s.start);
  const inCursor = segments.map(s => s.start + (s.end - s.start) / 2);
  const ribbons: ChordRibbon[] = [];
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const weight = Math.abs(widths[i]![j]!);
    if (!(weight > 0)) continue;
    const sourceSpan = (segments[i]!.end - segments[i]!.start) / 2 * weight / (outgoing[i] || 1);
    const targetSpan = (segments[j]!.end - segments[j]!.start) / 2 * weight / (incoming[j] || 1);
    const fs = outCursor[i]!, fe = fs + sourceSpan, ts = inCursor[j]!, te = ts + targetSpan;
    outCursor[i] = fe; inCursor[j] = te;
    ribbons.push({ i, j, fs, fe, ts, te, weight, colorValue: colors[i]![j]! - (compare?.[i]?.[j] ?? 0) });
  }
  const width = options.width ?? 760, height = options.height ?? 560, cx = width / 2, cy = height / 2 + 16;
  const outer = Math.min(width, height) * .34, inner = outer * .90;
  const diverging = colorMetric === 'residuals' || Boolean(compare);
  const values = ribbons.map(r => r.colorValue).filter(Number.isFinite);
  const limit = Math.max(1e-12, ...values.map(Math.abs));
  const min = Math.min(...values, 0), max = Math.max(...values, 1e-12);
  let body = '';
  for (const ribbon of ribbons.slice().sort((a, b) => b.weight - a.weight)) {
    const fill = diverging ? divergingColor(ribbon.colorValue, limit) : sequentialColor(ribbon.colorValue, min, max);
    body += `<path d="${chordRibbon(cx, cy, inner, ribbon)}" fill="${fill}" fill-opacity="${options.alpha ?? .6}"><title>${esc(fit.data.labels[ribbon.i])} → ${esc(fit.data.labels[ribbon.j])}: ${fmt(ribbon.weight)}</title></path>`;
  }
  segments.forEach((segment, i) => {
    body += `<path d="${arcPath(cx, cy, inner, outer, segment.start, segment.end)}" fill="${(options.colors ?? CHORD_COLORS)[i % (options.colors ?? CHORD_COLORS).length]}" stroke="#fff" stroke-width="1"/>`;
    const r = outer + 20, x = cx + r * Math.cos(segment.mid), y = cy + r * Math.sin(segment.mid);
    body += `<text class="axis" text-anchor="middle" x="${x}" y="${y + 4}">${esc(fit.data.labels[i])}</text>`;
  });
  const id = `ld-chord-${++svgCounter}`;
  body += colorLegend(id, width - 72, 92, 92, colorMetric === 'residuals' ? 'z' : compare ? 'difference' : colorMetric, diverging ? -limit : min, diverging ? limit : max, diverging);
  const subtitle = `ribbon width = ${widthMetric} · fill = ${compare ? `${colorMetric} difference` : colorMetric}`;
  return frame(body, options, 'Transition chord diagram', subtitle, true);
}

export interface PolarOptions extends LSAPlotOptions {
  style?: 'rose' | 'wedge';
  fill?: 'residuals' | 'prob' | 'lift';
  size?: 'count' | 'prob';
  labels?: 'all' | 'auto' | 'none';
  minShow?: number;
  labelSize?: number;
}

/** Direct SVG port of lagdynamics' rose/wedge polar sunburst. */
export function plotPolar(fit: LSAFit, options: PolarOptions = {}): string {
  const style = options.style ?? 'rose', fillKey = options.fill ?? 'residuals', sizeKey = options.size ?? 'count';
  const labelMode = options.labels ?? (style === 'rose' ? 'all' : 'auto');
  const fills = cleanWeight(fit, fillKey === 'residuals' ? 'adj_res' : fillKey);
  const sizes = cleanWeight(fit, sizeKey);
  const n = fit.data.nStates, width = options.width ?? 760, height = options.height ?? 560;
  const cx = width / 2 - 20, cy = height / 2 + 18, radius = Math.min(width, height) * .31;
  const srcIn = radius * .34, srcOut = radius * .50, ring0 = radius * .54, ring1 = radius;
  const values = fills.flat().filter(Number.isFinite);
  const diverging = fillKey === 'residuals', limit = Math.max(1e-12, ...values.map(Math.abs));
  const min = Math.min(0, ...values), max = Math.max(1e-12, ...values);
  const color = (value: number): string => diverging ? divergingColor(value, limit) : sequentialColor(value, min, max);
  const gap = .05;
  let body = `<circle cx="${cx}" cy="${cy}" r="${ring0}" fill="none" stroke="#e0e0e0"/><circle cx="${cx}" cy="${cy}" r="${ring1}" fill="none" stroke="#e0e0e0"/>`;
  const sourceMid: number[] = [];

  if (style === 'rose') {
    const sector = (2 * Math.PI - gap * n) / n;
    const globalMax = Math.max(1e-12, ...sizes.flat().filter(v => Number.isFinite(v) && v > 0));
    for (let i = 0; i < n; i++) {
      const start = -Math.PI / 2 + i * (sector + gap), end = start + sector;
      sourceMid.push((start + end) / 2);
      body += `<path d="${arcPath(cx, cy, srcIn, srcOut, start, end)}" fill="#ebebeb" stroke="#fff"/>`;
      const pad = sector * .04, slot = (sector - 2 * pad) / n;
      const modal = sizes[i]!.indexOf(Math.max(...sizes[i]!));
      for (let j = 0; j < n; j++) {
        const amount = sizes[i]![j]!;
        if (!(amount > 0) || !Number.isFinite(amount)) continue;
        const angle = start + pad + (j + .5) * slot;
        const outer = ring0 + Math.sqrt(clamp(amount / globalMax)) * (ring1 - ring0);
        const value = options.significant && !(fit.pValues[i]![j]! < fit.params.alpha) ? NaN : fills[i]![j]!;
        body += `<path d="${arcPath(cx, cy, ring0, outer, angle - slot * .42, angle + slot * .42)}" fill="${color(value)}" stroke="#fff" stroke-width=".5"><title>${esc(fit.data.labels[i])} → ${esc(fit.data.labels[j])}: ${fmt(amount)}</title></path>`;
        if (labelMode === 'all' || (labelMode === 'auto' && j === modal)) body += polarLabel(cx, cy, ring1 + 10, angle, fit.data.labels[j]!);
      }
    }
  } else {
    const outgoing = fit.observed.map(row => sum(row.map(v => Number.isFinite(v) && v > 0 ? v : 0)));
    const total = sum(outgoing) || 1;
    let cursor = -Math.PI / 2;
    for (let i = 0; i < n; i++) {
      const sector = outgoing[i]! / total * (2 * Math.PI - gap * n), start = cursor, end = start + sector;
      cursor = end + gap; sourceMid.push((start + end) / 2);
      body += `<path d="${arcPath(cx, cy, srcIn, srcOut, start, end)}" fill="#ebebeb" stroke="#fff"/>`;
      const row = fit.observed[i]!, rowTotal = sum(row), keep = row.map((v, j) => ({ j, share: rowTotal ? v / rowTotal : 0 })).filter(d => d.share >= (options.minShow ?? .01) && d.share > 0);
      const keepTotal = sum(keep.map(d => d.share)) || 1;
      let wedgeCursor = start + sector * .02;
      for (const entry of keep) {
        const wedge = entry.share / keepTotal * sector * .96, a0 = wedgeCursor, a1 = a0 + wedge;
        wedgeCursor = a1;
        const value = options.significant && !(fit.pValues[i]![entry.j]! < fit.params.alpha) ? NaN : fills[i]![entry.j]!;
        body += `<path d="${arcPath(cx, cy, ring0, ring1, a0, a1)}" fill="${color(value)}" stroke="#fff" stroke-width=".5"><title>${esc(fit.data.labels[i])} → ${esc(fit.data.labels[entry.j])}: ${fmt(entry.share)}</title></path>`;
        if (labelMode === 'all' || (labelMode === 'auto' && wedge >= .05)) body += polarLabel(cx, cy, ring1 + 10, (a0 + a1) / 2, fit.data.labels[entry.j]!);
      }
    }
  }

  sourceMid.forEach((angle, i) => {
    const r = (srcIn + srcOut) / 2, x = cx + r * Math.cos(angle), y = cy + r * Math.sin(angle);
    body += `<text class="small" font-weight="700" text-anchor="middle" transform="translate(${x} ${y}) rotate(${tangential(angle)})">${esc(fit.data.labels[i])}</text>`;
  });
  const id = `ld-polar-${++svgCounter}`;
  body += colorLegend(id, width - 70, 100, 92, fillKey === 'residuals' ? 'z' : fillKey === 'prob' ? 'P(to | from)' : 'lift', diverging ? -limit : min, diverging ? limit : max, diverging);
  const subtitle = style === 'rose'
    ? `${fit.method} engine, lag ${fit.params.lag} · equal slots · bar height = ${sizeKey}, fill = ${fillKey === 'residuals' ? 'z' : fillKey}`
    : `${fit.method} engine, lag ${fit.params.lag} · sector = source volume, wedge width = frequency, fill = ${fillKey === 'residuals' ? 'z' : fillKey}`;
  return frame(body, options, `Transition sunburst - ${fillKey === 'residuals' ? 'adjusted residuals' : fillKey}`, subtitle, true);
}

function polarLabel(cx: number, cy: number, radius: number, angle: number, label: string): string {
  const x = cx + radius * Math.cos(angle), y = cy + radius * Math.sin(angle);
  const left = Math.cos(angle) < 0, rotation = angle * 180 / Math.PI + (left ? 180 : 0);
  return `<text class="tiny" fill="#555" text-anchor="${left ? 'end' : 'start'}" transform="translate(${x} ${y}) rotate(${rotation})">${esc(label)}</text>`;
}

export interface ForestOptions extends LSAPlotOptions {
  metric?: 'residuals' | 'count' | 'prob' | 'yules_q';
  top?: number;
  showNonsignificant?: boolean;
  labelSize?: number;
}

interface ForestRow { edge: string; estimate: number; low: number; high: number; stable: boolean; direction: number }

/** Radial bootstrap/certainty forest, matching lagdynamics' bootstrap circles. */
export function plotForest(result: LSABootstrapResult | LSACertaintyResult, options: ForestOptions = {}): string {
  const metric = options.metric ?? (result.kind === 'lsa_certainty' ? 'prob' : 'residuals');
  let rows: ForestRow[] = result.edges.map(edge => {
    if (result.kind === 'lsa_certainty') {
      const e = edge as LSACertaintyEdge;
      return { edge: `${e.from} → ${e.to}`, estimate: e.probObserved, low: e.probCILow, high: e.probCIHigh, stable: e.stable, direction: e.adjResObserved };
    }
    const e = edge as LSABootstrapEdge;
    if (metric === 'count') return { edge: `${e.from} → ${e.to}`, estimate: e.observed, low: e.countCILow, high: e.countCIHigh, stable: e.adjResStable, direction: e.adjResObserved };
    if (metric === 'prob') return { edge: `${e.from} → ${e.to}`, estimate: e.probObserved, low: e.probCILow, high: e.probCIHigh, stable: e.adjResStable, direction: e.adjResObserved };
    if (metric === 'yules_q') return { edge: `${e.from} → ${e.to}`, estimate: e.yulesQObserved, low: e.yulesQCILow, high: e.yulesQCIHigh, stable: e.adjResStable, direction: e.adjResObserved };
    return { edge: `${e.from} → ${e.to}`, estimate: e.adjResObserved, low: e.adjResCILow, high: e.adjResCIHigh, stable: e.adjResStable, direction: e.adjResObserved };
  }).filter(row => Number.isFinite(row.estimate) && Number.isFinite(row.low) && Number.isFinite(row.high));
  if (options.showNonsignificant === false) rows = rows.filter(row => row.stable);
  rows.sort((a, b) => a.edge.localeCompare(b.edge));
  if (options.top !== undefined) {
    const selected = rows.slice().sort((a, b) => Math.abs(b.estimate) - Math.abs(a.estimate)).slice(0, options.top);
    const keep = new Set(selected.map(row => row.edge));
    rows = rows.filter(row => keep.has(row.edge));
  }
  const width = options.width ?? 760, height = options.height ?? 560, cx = width / 2 - 18, cy = height / 2 + 15;
  const outer = Math.min(width, height) * .29, inner = outer * .55;
  const minValue = Math.min(0, ...rows.map(row => row.low)), maxValue = Math.max(0, ...rows.map(row => row.high)) * 1.02;
  const toRadius = (value: number): number => inner + clamp((value - minValue) / (maxValue - minValue || 1)) * (outer - inner);
  const nullRadius = toRadius(0);
  let body = `<circle cx="${cx}" cy="${cy}" r="${inner}" fill="none" stroke="#d9d9d9"/><circle cx="${cx}" cy="${cy}" r="${outer}" fill="none" stroke="#d9d9d9"/><circle cx="${cx}" cy="${cy}" r="${nullRadius}" fill="none" stroke="#888" stroke-dasharray="5 4"/>`;
  rows.forEach((row, i) => {
    const angle = -Math.PI / 2 + 2 * Math.PI * i / Math.max(1, rows.length);
    const point = (radius: number): [number, number] => [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
    const start = point(inner), end = point(outer), low = point(toRadius(row.low)), high = point(toRadius(row.high)), estimate = point(toRadius(row.estimate));
    const color = !row.stable ? '#b3b3b3' : row.direction > 0 ? DIV_HIGH : DIV_LOW;
    body += `<line x1="${start[0]}" y1="${start[1]}" x2="${end[0]}" y2="${end[1]}" stroke="#ebebeb"/>`;
    body += `<line x1="${low[0]}" y1="${low[1]}" x2="${high[0]}" y2="${high[1]}" stroke="${color}" stroke-width="3" stroke-linecap="round"/>`;
    body += `<rect x="${estimate[0] - 3}" y="${estimate[1] - 3}" width="6" height="6" fill="${color}"/>`;
    const label = point(outer + 12), left = Math.cos(angle) < 0, rotation = angle * 180 / Math.PI + (left ? 180 : 0);
    body += `<text class="tiny" fill="${color}" text-anchor="${left ? 'end' : 'start'}" transform="translate(${label[0]} ${label[1]}) rotate(${rotation})">${esc(row.edge)}</text>`;
  });
  body += `<g transform="translate(${width - 145} ${height - 74})"><rect width="10" height="10" fill="${DIV_HIGH}"/><text class="small" x="15" y="9">over-represented</text><rect y="18" width="10" height="10" fill="${DIV_LOW}"/><text class="small" x="15" y="27">avoided</text><rect y="36" width="10" height="10" fill="#b3b3b3"/><text class="small" x="15" y="45">n.s.</text></g>`;
  const resamples = result.kind === 'lsa_bootstrap' ? `${result.iterations} resamples` : 'analytic posterior';
  const subtitle = `${resamples} · spoke = ${Math.round(result.confidenceLevel * 100)}% CI, square = estimate, dashed ring = null`;
  const metricTitle = ({ residuals: 'adjusted residuals', count: 'counts', prob: 'probabilities', yules_q: "Yule's Q" } as const)[metric];
  return frame(body, options, `${result.kind === 'lsa_bootstrap' ? 'Bootstrap' : 'Analytic'} forest - ${metricTitle}`, subtitle, true);
}

export interface ComparisonPlotOptions extends LSAPlotOptions {
  style?: 'barrel' | 'heatmap';
  top?: number;
  value?: 'prob' | 'count';
  rank?: 'frequency' | 'effect';
}

function logOdds(fit: LSAFit): Matrix {
  const observed = fit.observed, n = observed.length;
  const rowTotals = observed.map(sum), colTotals = Array.from({ length: n }, (_, j) => sum(observed.map(row => row[j]!))), total = sum(rowTotals);
  return observed.map((row, i) => row.map((cell, j) => {
    if (!Number.isFinite(fit.adjustedResiduals[i]![j]!)) return NaN;
    let a = cell, b = rowTotals[i]! - a, c = colTotals[j]! - a, d = total - rowTotals[i]! - colTotals[j]! + a;
    if (a === 0 || b === 0 || c === 0 || d === 0) { a += .5; b += .5; c += .5; d += .5; }
    return Math.log(a * d / (b * c));
  }));
}

function comparisonHeatmap(result: LSAComparison | LSABayesComparison, options: ComparisonPlotOptions): string {
  const width = options.width ?? 760, height = options.height ?? 560, labels = result.fits[0].data.labels, n = labels.length;
  const left = 138, top = 82, right = 112, bottom = 90, cell = Math.min((width - left - right) / n, (height - top - bottom) / n);
  const limit = Math.max(1e-12, ...result.edges.map(edge => Math.abs(edge.diff)).filter(Number.isFinite));
  const lookup = new Map(result.edges.map(edge => [`${edge.from}\0${edge.to}`, edge]));
  let body = '';
  for (let i = 0; i < n; i++) {
    body += `<text class="axis mono" text-anchor="end" x="${left - 9}" y="${top + (i + .62) * cell}">${esc(labels[i])}</text>`;
    for (let j = 0; j < n; j++) {
      const edge = lookup.get(`${labels[i]}\0${labels[j]}`), value = edge?.diff ?? NaN, x = left + j * cell, y = top + i * cell;
      body += `<rect x="${x}" y="${y}" width="${cell}" height="${cell}" fill="${divergingColor(value, limit, CMP_LOW, CMP_MID, CMP_HIGH)}" stroke="#fff"/>`;
      if (Number.isFinite(value)) body += `<text class="small" text-anchor="middle" x="${x + cell / 2}" y="${y + cell / 2 + 3}" font-weight="${edge?.significant ? '700' : '400'}">${fmt(value, 2)}</text>`;
    }
  }
  for (let j = 0; j < n; j++) body += `<text class="axis" text-anchor="end" transform="translate(${left + (j + .55) * cell},${top + n * cell + 12}) rotate(-45)">${esc(labels[j])}</text>`;
  const id = `ld-cmp-${++svgCounter}`;
  body += colorLegend(id, left + n * cell + 30, top + 18, Math.max(90, n * cell - 36), 'diff', -limit, limit, true, CMP_LOW, CMP_HIGH);
  body += `<text class="axis" text-anchor="middle" x="${left + n * cell / 2}" y="${height - 20}">Next state</text>`;
  const significant = result.edges.filter(edge => edge.significant).length;
  const count = result.kind === 'lsa_comparison' ? `${result.iterations} permutations` : `${result.draws} posterior draws`;
  const subtitle = `${result.kind === 'lsa_comparison' ? result.measure : 'probability'} difference · ${count} · ${significant} significant edges · blue = ${result.groups[0]} higher, red = ${result.groups[1]} higher`;
  return frame(body, options, `Group difference: ${result.groups[0]} vs ${result.groups[1]}`, subtitle);
}

/** Canonical lagdynamics back-to-back comparison barrel. */
export function plotComparison(
  result: LSAComparison | LSAPairwiseComparison | LSABayesComparison | LSABayesPairwiseComparison,
  options: ComparisonPlotOptions = {},
): string | Record<string, string> {
  if (result.kind === 'lsa_comparison_pairwise' || result.kind === 'lsa_bayes_pairwise') {
    return Object.fromEntries(Object.entries(result.comparisons).map(([key, value]) => [key, plotComparison(value, options) as string]));
  }
  if ((options.style ?? 'barrel') === 'heatmap') return comparisonHeatmap(result, options);
  const fitA = result.fits[0], fitB = result.fits[1], value = options.value ?? 'prob', rank = options.rank ?? 'frequency';
  const labels = fitA.data.labels, index = new Map(labels.map((label, i) => [label, i]));
  const logA = logOdds(fitA), logB = logOdds(fitB);
  const rows = result.edges.map(edge => {
    const i = index.get(edge.from)!, j = index.get(edge.to)!;
    const frequency = fitA.observed[i]![j]! + fitB.observed[i]![j]!;
    const effect = Math.max(Math.abs(logA[i]![j]!), Math.abs(logB[i]![j]!));
    return { edge, i, j, frequency, effect };
  }).sort((a, b) => (rank === 'frequency' ? b.frequency - a.frequency : b.effect - a.effect)).slice(0, options.top ?? 12);
  const width = options.width ?? 760, height = Math.max(options.height ?? 560, 142 + rows.length * 30);
  const labelX = 170, center = width / 2 + 55, right = width - 75, top = 96, rowGap = 30;
  const lengths = rows.flatMap(row => value === 'prob' ? [fitA.probability[row.i]![row.j]!, fitB.probability[row.i]![row.j]!] : [fitA.observed[row.i]![row.j]!, fitB.observed[row.i]![row.j]!]);
  const maxLength = Math.max(1e-12, ...lengths), halfWidth = Math.min(center - labelX - 35, right - center), scale = halfWidth / maxLength, gutter = Math.max(7, maxLength * scale * .06);
  const maxDiff = Math.max(1e-12, ...rows.map(row => Math.abs(row.edge.diff)));
  let body = `<line x1="${center}" x2="${center}" y1="${top - 26}" y2="${top + rows.length * rowGap}" stroke="#bdbdbd"/>`;
  body += `<text class="small" text-anchor="end" x="${center - 18}" y="${top - 32}">${esc(result.groups[0])}  «</text><text class="small" x="${center + 18}" y="${top - 32}">»  ${esc(result.groups[1])}</text>`;
  rows.forEach((row, rowIndex) => {
    const y = top + rowIndex * rowGap, lenA = lengths[rowIndex * 2]! * scale, lenB = lengths[rowIndex * 2 + 1]! * scale;
    const colorA = divergingColor(clamp(logA[row.i]![row.j]!, -3, 3), 3, CMP_LOW, CMP_MID, CMP_HIGH);
    const colorB = divergingColor(clamp(logB[row.i]![row.j]!, -3, 3), 3, CMP_LOW, CMP_MID, CMP_HIGH);
    const darkness = Math.round(255 * (1 - .85 * Math.abs(row.edge.diff) / maxDiff)), winner = `rgb(${darkness},${darkness},${darkness})`;
    body += `<line x1="${labelX}" x2="${right}" y1="${y + 9}" y2="${y + 9}" stroke="#ebebeb"/>`;
    body += `<text class="tiny mono" text-anchor="end" x="${labelX - 8}" y="${y + 3}">${esc(row.edge.from)} → ${esc(row.edge.to)}</text>`;
    body += `<rect x="${center - gutter - lenA}" y="${y - 7}" width="${lenA}" height="14" fill="${colorA}" stroke="${row.edge.diff > 0 ? winner : '#fff'}" stroke-width="${row.edge.diff > 0 ? 1.2 : .4}"/>`;
    body += `<rect x="${center + gutter}" y="${y - 7}" width="${lenB}" height="14" fill="${colorB}" stroke="${row.edge.diff < 0 ? winner : '#fff'}" stroke-width="${row.edge.diff < 0 ? 1.2 : .4}"/>`;
    body += `<text class="tiny" fill="#666" text-anchor="end" x="${center - gutter - lenA - 4}" y="${y + 3}">${fmt(fitA.observed[row.i]![row.j]!, 0)}</text><text class="tiny" fill="#666" x="${center + gutter + lenB + 4}" y="${y + 3}">${fmt(fitB.observed[row.i]![row.j]!, 0)}</text>`;
    const p = row.edge.pAdjusted, pText = !Number.isFinite(p) ? '–' : p < .001 ? '<.001' : fmt(p, 3);
    body += `<rect x="${center - 19}" y="${y - 8}" width="38" height="16" rx="3" fill="#fff" stroke="#d4d4d4"/><text class="tiny" font-weight="${row.edge.significant ? '700' : '400'}" text-anchor="middle" x="${center}" y="${y + 3}">${pText}${row.edge.significant ? '*' : ''}</text>`;
  });
  const id = `ld-barrel-${++svgCounter}`;
  body += colorLegend(id, width - 56, height - 118, 72, 'log OR', -3, 3, true, CMP_LOW, CMP_HIGH);
  body += `<text class="axis" text-anchor="middle" x="${center}" y="${height - 18}">${value === 'prob' ? 'P(to | from)' : 'count'}</text>`;
  const significant = rows.filter(row => row.edge.significant).length;
  const subtitle = `bar length = ${value === 'prob' ? 'P(to | from)' : 'count'} · fill = log odds ratio · centre = difference p · ${significant} of ${rows.length} shown significant · rows by ${rank}`;
  return frame(body, { ...options, height }, `Transition comparison: ${result.groups[0]} vs ${result.groups[1]}`, subtitle, true);
}

export function plotLSA(
  input: LSAFit | LSAGroup,
  type: 'heatmap' | 'network' | 'chord' | 'sunburst' = 'heatmap',
  options: LSAPlotOptions = {},
): string | Record<string, string> {
  if (input.kind === 'lsa_group') {
    return Object.fromEntries(input.levels.map(group => [group, plotLSA(input.groups[group]!, type, { ...options, title: options.title ?? group }) as string]));
  }
  if (type === 'network') return plotTransitions(input, options);
  if (type === 'chord') return plotChords(input, options);
  if (type === 'sunburst') return plotPolar(input, options);
  return plotLSAHeatmap(input, options);
}
